INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4a062d7b-5f43-5ebc-ac6b-6029656a13cf', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 1, 1, 'Therefore seeing we have this ministry, even as we obtained mercy, we don''t faint.'),
  ('d9f047bc-78a5-5dbf-a392-5f2e4997945d', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 2, 2, 'But we have renounced the hidden things of shame, not walking in craftiness, nor handling the word of God deceitfully; but by the manifestation of the truth commending ourselves to every man''s conscience in the sight of God.'),
  ('0768081d-ba3e-5b9b-ad93-b3a2772df963', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 3, 3, 'Even if our Good News is veiled, it is veiled in those who perish;'),
  ('3c03fb26-752c-5439-ae14-0ee7271e9d24', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 4, 4, 'in whom the god of this world has blinded the minds of the unbelieving, that the light of the Good News of the glory of Christ, who is the image of God, should not dawn on them.'),
  ('9db38b16-5e06-53ba-a941-443182dd4007', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 5, 5, 'For we don''t preach ourselves, but Christ Jesus as Lord, and ourselves as your servants for Jesus'' sake;'),
  ('4de03ad9-af23-5c7c-aadb-718d485eef39', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 6, 6, 'seeing it is God who said, "Light will shine out of darkness," who has shone in our hearts, to give the light of the knowledge of the glory of God in the face of Jesus Christ.'),
  ('7c549e98-4430-5f57-a9fe-d8aeb2c409f3', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 7, 7, 'But we have this treasure in clay vessels, that the exceeding greatness of the power may be of God, and not from ourselves.'),
  ('c2dec7de-06f8-51fe-a418-068adf056086', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 8, 8, 'We are pressed on every side, yet not crushed; perplexed, yet not to despair;'),
  ('4166833b-6cbe-540b-ad2a-f43d0137ff9c', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 9, 9, 'pursued, yet not forsaken; struck down, yet not destroyed;'),
  ('dff640bb-e795-5861-a8b4-785b49ed5591', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 10, 10, 'always carrying in the body the putting to death of the Lord Jesus, that the life of Jesus may also be revealed in our body.'),
  ('73e5bdee-0b2c-5582-afad-7b6d6a8446c3', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 11, 11, 'For we who live are always delivered to death for Jesus'' sake, that the life also of Jesus may be revealed in our mortal flesh.'),
  ('0fbffb9a-d429-5c02-ab9b-e2f0939ac03b', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 12, 12, 'So then death works in us, but life in you.'),
  ('a8755487-8a6e-54b9-afe9-6ec676336a02', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 13, 13, 'But having the same spirit of faith, according to that which is written, "I believed, and therefore I spoke." We also believe, and therefore also we speak;'),
  ('6372db16-c132-541e-ace3-5facb36ff666', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 14, 14, 'knowing that he who raised the Lord Jesus will raise us also with Jesus, and will present us with you.'),
  ('168628cc-2f1c-5ce1-a777-380cb961d495', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 15, 15, 'For all things are for your sakes, that the grace, being multiplied through the many, may cause the thanksgiving to abound to the glory of God.'),
  ('6c8c5783-0092-5011-a2a1-fd743cde0c95', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 16, 16, 'Therefore we don''t faint, but though our outward man is decaying, yet our inward man is renewed day by day.'),
  ('41f1dbb5-aa71-5071-af32-4e64431cab25', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 17, 17, 'For our light affliction, which is for the moment, works for us more and more exceedingly an eternal weight of glory;'),
  ('1ae0c119-32ca-553c-ac76-a9ce82b1ec6e', '834714e1-3449-52d3-a1f0-d9725e0e537b', NULL, 18, 18, 'while we don''t look at the things which are seen, but at the things which are not seen. For the things which are seen are temporal, but the things which are not seen are eternal.'),
  ('7a95e557-a459-53d8-a94b-add6264f061c', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 1, 1, 'For we know that if the earthly house of our tent is dissolved, we have a building from God, a house not made with hands, eternal, in the heavens.'),
  ('4ee37ac3-4465-5c17-af9b-d040f1d6c4ce', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 2, 2, 'For most certainly in this we groan, longing to be clothed with our habitation which is from heaven;'),
  ('d11758d0-d242-5b34-ad26-fbfab77caedf', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 3, 3, 'if so be that being clothed we will not be found naked.'),
  ('deabfa90-46a8-574f-a62f-f3f779bf2146', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 4, 4, 'For indeed we who are in this tent do groan, being burdened; not that we desire to be unclothed, but that we desire to be clothed, that what is mortal may be swallowed up by life.'),
  ('199d0e87-7025-59d2-a759-8a25ecc84715', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 5, 5, 'Now he who made us for this very thing is God, who also gave to us the down payment of the Spirit.'),
  ('0c8ca30b-ff30-5e62-a3a7-e9860f20e4a1', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 6, 6, 'Therefore, we are always confident and know that while we are at home in the body, we are absent from the Lord;'),
  ('9187643b-82b7-59e3-acd0-2dba1e799779', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 7, 7, 'for we walk by faith, not by sight.'),
  ('9a7cfb2f-1a70-56e2-af84-02860df4816e', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 8, 8, 'We are courageous, I say, and are willing rather to be absent from the body, and to be at home with the Lord.'),
  ('5d0a4fdf-24b1-5f42-acf9-a68260f1152d', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 9, 9, 'Therefore also we make it our aim, whether at home or absent, to be well pleasing to him.'),
  ('6c48e2b3-f123-50cb-aab9-a409b1bf675d', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 10, 10, 'For we must all be revealed before the judgment seat of Christ; that each one may receive the things in the body, according to what he has done, whether good or bad.'),
  ('73f2bdd6-f60f-5f42-a3ea-a5c0f06ff005', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 11, 11, 'Knowing therefore the fear of the Lord, we persuade men, but we are revealed to God; and I hope that we are revealed also in your consciences.'),
  ('d8c709af-ee71-5316-a506-adde9957c238', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 12, 12, 'For we are not commending ourselves to you again, but speak as giving you occasion of boasting on our behalf, that you may have something to answer those who boast in appearance, and not in heart.'),
  ('5ba59fa4-fefd-5de8-aceb-f01596c762a7', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 13, 13, 'For if we are beside ourselves, it is for God. Or if we are of sober mind, it is for you.'),
  ('0c35c8cd-237e-5a2e-af22-80965869ac40', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 14, 14, 'For the love of Christ constrains us; because we judge thus, that one died for all, therefore all died.'),
  ('b63c8be2-a754-5e37-ab33-4613326e679e', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 15, 15, 'He died for all, that those who live should no longer live to themselves, but to him who for their sakes died and rose again.'),
  ('9f1fe59f-26d9-5a72-abcc-6ebe1eb785b9', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 16, 16, 'Therefore we know no one after the flesh from now on. Even though we have known Christ after the flesh, yet now we know him so no more.'),
  ('fc22f95c-00a2-5a67-afbf-b460979f5968', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 17, 17, 'Therefore if anyone is in Christ, he is a new creation. The old things have passed away. Behold, all things have become new.'),
  ('fa3d4641-c7b9-5fc5-a2cc-855bba3af429', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 18, 18, 'But all things are of God, who reconciled us to himself through Jesus Christ, and gave to us the ministry of reconciliation;'),
  ('54c71af6-6c55-5b4b-a3c3-807fab98c7e5', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 19, 19, 'namely, that God was in Christ reconciling the world to himself, not reckoning to them their trespasses, and having committed to us the word of reconciliation.'),
  ('5f416f8f-b085-5b4f-a481-f5378dbd47b6', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 20, 20, 'We are therefore ambassadors on behalf of Christ, as though God were entreating by us: we beg you on behalf of Christ, be reconciled to God.'),
  ('07c09b63-3897-527d-a468-dafc02c104ab', 'b3f8ecc1-7a06-55a4-a02b-25f8197d2b0c', NULL, 21, 21, 'For him who knew no sin he made to be sin on our behalf; so that in him we might become the righteousness of God.'),
  ('4c19492a-c263-56dc-a040-b25fb47691eb', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 1, 1, 'Working together, we entreat also that you not receive the grace of God in vain,'),
  ('e70883e4-c8f1-5540-a02b-19c4b4935cfe', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 2, 2, 'for he says, "At an acceptable time I listened to you, in a day of salvation I helped you." Behold, now is the acceptable time. Behold, now is the day of salvation.'),
  ('70f6d1a9-7fa1-5fbd-a624-2a2d8a3dc7ba', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 3, 3, 'We give no occasion of stumbling in anything, that our service may not be blamed,'),
  ('0a0ab1c5-a212-5d1d-a84c-b8bb7e842880', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 4, 4, 'but in everything commending ourselves, as servants of God, in great endurance, in afflictions, in hardships, in distresses,'),
  ('f89699f7-db3d-55b9-a97a-0a92308067fe', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 5, 5, 'in beatings, in imprisonments, in riots, in labors, in watchings, in fastings;'),
  ('8ff7ce9b-54ce-5b6b-af42-1b5ef3ab82a4', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 6, 6, 'in pureness, in knowledge, in patience, in kindness, in the Holy Spirit, in sincere love,'),
  ('13a773dd-a07e-5c93-a3cb-cc3e9be89a8d', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 7, 7, 'in the word of truth, in the power of God; by the armor of righteousness on the right hand and on the left,'),
  ('f09c2615-7793-5c6c-a207-ffc2d678e65a', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 8, 8, 'by glory and dishonor, by evil report and good report; as deceivers, and yet true;'),
  ('e84dfc23-29fb-530f-a565-32ee80404222', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 9, 9, 'as unknown, and yet well known; as dying, and behold, we live; as punished, and not killed;'),
  ('61e6ce01-b70d-5425-a06f-d02bcfafa6d2', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 10, 10, 'as sorrowful, yet always rejoicing; as poor, yet making many rich; as having nothing, and yet possessing all things.'),
  ('5222a994-158d-5e45-ac67-a7df3c2707f9', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 11, 11, 'Our mouth is open to you, Corinthians. Our heart is enlarged.'),
  ('2ee2997e-df86-5bf6-ae56-2d67e2a80be8', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 12, 12, 'You are not restricted by us, but you are restricted by your own affections.'),
  ('f7b9c26d-9565-5da2-a435-02d656906c0a', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 13, 13, 'Now in return, I speak as to my children, you also be open wide.'),
  ('61866f0c-905d-559b-a797-79b48953932b', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 14, 14, 'Don''t be unequally yoked with unbelievers, for what fellowship have righteousness and iniquity? Or what fellowship has light with darkness?'),
  ('ab7577d2-b729-5a8d-a873-7fa5eeb25904', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 15, 15, 'What agreement has Christ with Belial? Or what portion has a believer with an unbeliever?'),
  ('9cf7c506-5f46-504d-af54-87f7a740ecff', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 16, 16, 'What agreement has a temple of God with idols? For you are a temple of the living God. Even as God said, "I will dwell in them, and walk in them; and I will be their God, and they will be my people."'),
  ('7f3f30d7-ab54-5597-a3e5-acb18ecec9b3', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 17, 17, 'Therefore, "''Come out from among them, and be separate,'' says the Lord. ''Touch no unclean thing. I will receive you.'),
  ('9eaebb8b-4ecf-5ecc-acef-ef05eab349ae', '58657ea4-1f6c-5eb6-a504-b4fc6424e121', NULL, 18, 18, 'I will be to you a Father. You will be to me sons and daughters,'' says the Lord Almighty."'),
  ('16a1106c-1ecb-5f02-ac34-25d23495e2bf', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 1, 1, 'Having therefore these promises, beloved, let us cleanse ourselves from all defilement of flesh and spirit, perfecting holiness in the fear of God.'),
  ('c3d5c17b-3da8-5c20-a7aa-c7c9f2de6b57', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 2, 2, 'Open your hearts to us. We wronged no one. We corrupted no one. We took advantage of no one.'),
  ('c936aedc-1a33-5cd5-abcb-30b6dced22c6', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 3, 3, 'I say this not to condemn you, for I have said before, that you are in our hearts to die together and live together.'),
  ('82b70a66-60c3-56c9-a87c-0584e6079a55', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 4, 4, 'Great is my boldness of speech toward you. Great is my boasting on your behalf. I am filled with comfort. I overflow with joy in all our affliction.'),
  ('d7ea0435-fad0-58a6-a815-ee904cfabecf', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 5, 5, 'For even when we had come into Macedonia, our flesh had no relief, but we were afflicted on every side. Fightings were outside. Fear was inside.'),
  ('2055208c-28c8-50f6-a21e-c54a372a0c0d', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 6, 6, 'Nevertheless, he who comforts the lowly, God, comforted us by the coming of Titus;'),
  ('1b4d9a11-12b5-538f-a9d2-c88cbf4853e8', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 7, 7, 'and not by his coming only, but also by the comfort with which he was comforted in you, while he told us of your longing, your mourning, and your zeal for me; so that I rejoiced still more.'),
  ('cf9aabcb-8cc2-5a44-af2e-422ee701bd70', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 8, 8, 'For though I made you sorry with my letter, I do not regret it, though I did regret it. For I see that my letter made you sorry, though just for a while.'),
  ('c9be2eb3-04f6-5300-acf5-0dfbee1096da', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 9, 9, 'I now rejoice, not that you were made sorry, but that you were made sorry to repentance. For you were made sorry in a godly way, that you might suffer loss by us in nothing.'),
  ('303bc63f-9846-5bb4-ad30-8a9e3d495a1d', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 10, 10, 'For godly sorrow works repentance to salvation, which brings no regret. But the sorrow of the world works death.'),
  ('fa77c6e7-6929-5d9c-a258-46d9d218be85', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 11, 11, 'For behold, this same thing, that you were made sorry in a godly way, what earnest care it worked in you. Yes, what defense, indignation, fear, longing, zeal, and vengeance! In everything you demonstrated yourselves to be pure in the matter.'),
  ('05daea72-c61c-5497-a686-f9230bb8d81d', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 12, 12, 'So although I wrote to you, I wrote not for his cause that did the wrong, nor for his cause that suffered the wrong, but that your earnest care for us might be revealed in you in the sight of God.'),
  ('ce30cc46-c41d-5ab5-a862-008ae721aad9', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 13, 13, 'Therefore we have been comforted. In our comfort we rejoiced the more exceedingly for the joy of Titus, because his spirit has been refreshed by you all.'),
  ('440408a5-89f2-5a18-a94c-d25b5aaac1ec', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 14, 14, 'For if in anything I have boasted to him on your behalf, I was not disappointed. But as we spoke all things to you in truth, so our glorying also which I made before Titus was found to be truth.'),
  ('cf120d47-5aa6-580a-a128-d926411b46f6', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 15, 15, 'His affection is more abundantly toward you, while he remembers all of your obedience, how with fear and trembling you received him.'),
  ('abc50629-6268-5ec5-a24c-8f998d413fe3', '76a6f62d-4da7-5503-ad11-c325ec96da14', NULL, 16, 16, 'I rejoice that in everything I am confident concerning you.'),
  ('200e676e-323b-551c-af7f-ce40dd5680bc', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 1, 1, 'Moreover, brothers, we make known to you the grace of God which has been given in the assemblies of Macedonia;'),
  ('9dc44b5a-52af-5481-a5fe-09a86c0f8fa3', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 2, 2, 'how that in much proof of affliction the abundance of their joy and their deep poverty abounded to the riches of their liberality.'),
  ('36aa8ffc-090f-5bc5-a2f9-24e77be3656d', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 3, 3, 'For according to their power, I testify, yes and beyond their power, they gave of their own accord,'),
  ('52203e55-e4f0-5548-aab1-cd3d300c0c00', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 4, 4, 'begging us with much entreaty to receive this grace and the fellowship in the service to the saints.'),
  ('5a3a170e-d80d-5aff-a90b-72e32f8524f7', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 5, 5, 'This was not as we had hoped, but first they gave their own selves to the Lord, and to us through the will of God.'),
  ('01034799-8cdf-5e53-a40a-1bf53ea5ff30', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 6, 6, 'So we urged Titus, that as he made a beginning before, so he would also complete in you this grace.'),
  ('6fa5e694-c3ff-54e0-ac9c-c125dd9b55c8', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 7, 7, 'But as you abound in everything, in faith, utterance, knowledge, all earnestness, and in your love to us, see that you also abound in this grace.'),
  ('0ef2832b-ec33-5104-a9e7-cc831a404bc9', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 8, 8, 'I speak not by way of commandment, but as proving through the earnestness of others the sincerity also of your love.'),
  ('1b7e3ed5-a1e2-5248-a8ea-357c7bb8118c', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 9, 9, 'For you know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that you through his poverty might become rich.'),
  ('026397a8-e7c4-5535-a63a-a148a19d3e99', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 10, 10, 'I give a judgment in this: for this is expedient for you, who were the first to start a year ago, not only to do, but also to be willing.'),
  ('6ce9e781-7779-51a8-ab6d-f2a4b963def4', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 11, 11, 'But now complete the doing also, that as there was the readiness to be willing, so there may be the completion also out of your ability.'),
  ('bbe80285-66af-59ac-a431-fd8260389838', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 12, 12, 'For if the readiness is there, it is acceptable according to what you have, not according to what you don''t have.'),
  ('28602dcc-e884-51eb-ab5c-5fcff63c4387', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 13, 13, 'For this is not that others may be eased and you distressed,'),
  ('0064744d-40e2-54db-af7d-991e8f855d18', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 14, 14, 'but for equality. Your abundance at this present time supplies their lack, that their abundance also may become a supply for your lack; that there may be equality.'),
  ('10005730-e7f0-5710-acfb-59e2c28b4968', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 15, 15, 'As it is written, "He who gathered much had nothing left over, and he who gathered little had no lack."'),
  ('24328168-e4a0-5d17-a5b4-27428f658023', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 16, 16, 'But thanks be to God, who puts the same earnest care for you into the heart of Titus.'),
  ('666cdb5f-f71d-57b8-adc8-68605ec0cd34', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 17, 17, 'For he indeed accepted our exhortation, but being himself very earnest, he went out to you of his own accord.'),
  ('f51c37b5-8d8d-5401-ae69-aaa136f45ad1', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 18, 18, 'We have sent together with him the brother whose praise in the Good News is known through all the assemblies.'),
  ('27f8efa2-7b2b-51ee-a589-6fd5d86955f8', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 19, 19, 'Not only so, but who was also appointed by the assemblies to travel with us in this grace, which is served by us to the glory of the Lord himself, and to show our readiness.'),
  ('2b059557-b7bf-5ce8-a5ec-34299ebfae0b', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 20, 20, 'We are avoiding this, that any man should blame us concerning this abundance which is administered by us.'),
  ('84142c5b-e1b9-5c76-a31a-5b83c42acfc9', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 21, 21, 'Having regard for honorable things, not only in the sight of the Lord, but also in the sight of men.'),
  ('8a6e5896-d068-5d65-ac85-9355fa87e911', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 22, 22, 'We have sent with them our brother, whom we have many times proved earnest in many things, but now much more earnest, by reason of the great confidence which he has in you.'),
  ('cea782d3-77dd-58ec-a595-8e0cd177d9e8', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 23, 23, 'As for Titus, he is my partner and fellow worker for you. As for our brothers, they are the apostles of the assemblies, the glory of Christ.'),
  ('080761d2-78ee-5dca-a05d-a4cf3eca9c64', '4dd99c3d-dd87-565f-a4e4-247ea6f5327f', NULL, 24, 24, 'Therefore show the proof of your love to them in front of the assemblies, and of our boasting on your behalf.'),
  ('74a33188-36db-5844-a4c0-66c05006fe98', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 1, 1, 'It is indeed unnecessary for me to write to you concerning the service to the saints,'),
  ('8bf1355c-9b2f-53f4-a94c-845852dddfc4', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 2, 2, 'for I know your readiness, of which I boast on your behalf to them of Macedonia, that Achaia has been prepared for a year past. Your zeal has stirred up very many of them.'),
  ('d7588800-6b40-5869-ad6e-2ee506d204a3', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 3, 3, 'But I have sent the brothers that our boasting on your behalf may not be in vain in this respect, that, just as I said, you may be prepared,'),
  ('6ce492bc-0503-5b97-a424-897f5d064f48', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 4, 4, 'so that I won''t by any means, if there come with me any of Macedonia and find you unprepared, we (to say nothing of you) should be disappointed in this confident boasting.'),
  ('939a3c22-632f-55eb-afa3-c8c3c9422e73', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 5, 5, 'I thought it necessary therefore to entreat the brothers that they would go before to you, and arrange ahead of time the generous gift that you promised before, that the same might be ready as a matter of generosity, and not of greediness.'),
  ('8cf83de1-1a89-554c-aae4-fe782700659d', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 6, 6, 'Remember this: he who sows sparingly will also reap sparingly. He who sows bountifully will also reap bountifully.'),
  ('389906bb-d976-574c-a6d2-3d1fb2c363d5', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 7, 7, 'Let each man give according as he has determined in his heart; not grudgingly, or under compulsion; for God loves a cheerful giver.'),
  ('0402ea72-f915-54e9-aed7-ec37a8ce4f65', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 8, 8, 'And God is able to make all grace abound to you, that you, always having all sufficiency in everything, may abound to every good work.'),
  ('aeeb413b-0c4d-5674-a8d8-9f4e174d288f', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 9, 9, 'As it is written, "He has scattered abroad, he has given to the poor. His righteousness remains forever."'),
  ('271bbe2c-4040-5f37-a671-69ff60fa3718', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 10, 10, 'Now may he who supplies seed to the sower and bread for food, supply and multiply your seed for sowing, and increase the fruits of your righteousness;'),
  ('368c9232-7d94-5f01-a2e5-ab77078ff7c4', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 11, 11, 'you being enriched in everything to all liberality, which works through us thanksgiving to God.'),
  ('f5cf933a-104b-59b7-a922-a56a04d1799f', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 12, 12, 'For this service of giving that you perform not only makes up for lack among the saints, but abounds also through many givings of thanks to God;'),
  ('d3cb60c4-6689-5f5c-a2ec-c129749083da', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 13, 13, 'seeing that through the proof given by this service, they glorify God for the obedience of your confession to the Good News of Christ, and for the liberality of your contribution to them and to all;'),
  ('cf732803-22b3-5c1a-aeaf-f006368d9a48', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 14, 14, 'while they themselves also, with supplication on your behalf, yearn for you by reason of the exceeding grace of God in you.'),
  ('40f90dbe-1341-569f-a4d5-53161bbadc82', 'b121af94-71d5-5af9-a021-43ba16543274', NULL, 15, 15, 'Now thanks be to God for his unspeakable gift!'),
  ('64987bf8-8629-5491-a8fb-b52e4fe7cd3c', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 1, 1, 'Now I Paul, myself, entreat you by the humility and gentleness of Christ; I who in your presence am lowly among you, but being absent am bold toward you.'),
  ('6d63429d-d596-5518-a21d-db2c3be7641b', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 2, 2, 'Yes, I beg you that I may not, when present, show courage with the confidence with which I intend to be bold against some, who consider us to be walking according to the flesh.'),
  ('00313bd0-3b1d-5ef0-a6a0-8e05113267e5', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 3, 3, 'For though we walk in the flesh, we don''t wage war according to the flesh;'),
  ('fa5100d9-95b1-57c6-aab3-9c12509bd8c9', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 4, 4, 'for the weapons of our warfare are not of the flesh, but mighty before God to the throwing down of strongholds,'),
  ('da8155ce-e331-582a-a31c-43edc19e628a', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 5, 5, 'throwing down imaginations and every high thing that is exalted against the knowledge of God, and bringing every thought into captivity to the obedience of Christ;'),
  ('a2736040-7446-5ca9-aa28-a2ce67f001d8', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 6, 6, 'and being in readiness to avenge all disobedience, when your obedience will be made full.'),
  ('e71298f2-5ac4-5140-af21-5d8f185230f9', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 7, 7, 'Do you look at things only as they appear in front of your face? If anyone trusts in himself that he is Christ''s, let him consider this again with himself, that, even as he is Christ''s, so also we are Christ''s.'),
  ('5adbe163-6f53-5f16-a41f-b45287bff3db', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 8, 8, 'For though I should boast somewhat abundantly concerning our authority, (which the Lord gave for building you up, and not for casting you down) I will not be disappointed,'),
  ('cbd016d5-a5bb-536f-aae4-bee8c9c37669', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 9, 9, 'that I may not seem as if I desire to terrify you by my letters.'),
  ('897d4515-9e08-527e-a02c-3bbf0bdc3efb', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 10, 10, 'For, "His letters," they say, "are weighty and strong, but his bodily presence is weak, and his speech is despised."'),
  ('d20df9ac-ed8b-5f22-adb3-5f6ac8defc74', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 11, 11, 'Let such a person consider this, that what we are in word by letters when we are absent, such are we also in deed when we are present.'),
  ('ceda916c-95b6-5ea6-ad97-340019bbeaba', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 12, 12, 'For we are not bold to number or compare ourselves with some of those who commend themselves. But they themselves, measuring themselves by themselves, and comparing themselves with themselves, are without understanding.'),
  ('7b691f55-88c6-52cd-a70e-b24cad2017cd', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 13, 13, 'But we will not boast beyond proper limits, but within the boundaries with which God appointed to us, which reach even to you.'),
  ('7a267c87-6b8a-5e53-a6bb-e7afb3f326f6', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 14, 14, 'For we don''t stretch ourselves too much, as though we didn''t reach to you. For we came even as far as to you with the Good News of Christ,'),
  ('cef1de25-fb7f-5d2a-acfd-c1fda55a1752', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 15, 15, 'not boasting beyond proper limits in other men''s labors, but having hope that as your faith grows, we will be abundantly enlarged by you in our sphere of influence,'),
  ('af9ed9eb-7990-5053-a1a9-0e0d151d1858', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 16, 16, 'so as to preach the Good News even to the parts beyond you, not to boast in what someone else has already done.'),
  ('658a6d1c-574f-54d1-a481-722442970f7c', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 17, 17, 'But "he who boasts, let him boast in the Lord."'),
  ('822a8482-3145-5318-aff0-c103c5b518b9', '45b21f49-64bb-5a48-a698-0131d0908d62', NULL, 18, 18, 'For it isn''t he who commends himself who is approved, but whom the Lord commends.'),
  ('1bb029ed-e5f5-5da4-abf4-1e3337b99784', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 1, 1, 'I wish that you would bear with me in a little foolishness, but indeed you do bear with me.'),
  ('0fb7dcd3-84ca-5dfe-aebf-d9cf13d3de53', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 2, 2, 'For I am jealous over you with a godly jealousy. For I married you to one husband, that I might present you as a pure virgin to Christ.'),
  ('de3141a3-d1e0-5aec-ad82-10bb79dcb697', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 3, 3, 'But I am afraid that somehow, as the serpent deceived Eve in his craftiness, so your minds might be corrupted from the simplicity that is in Christ.'),
  ('903689e1-6a7d-5e79-a17f-2c2803e09cac', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 4, 4, 'For if he who comes preaches another Jesus, whom we did not preach, or if you receive a different spirit, which you did not receive, or a different "good news", which you did not accept, you put up with that well enough.'),
  ('f0c76505-19e5-5da1-a842-36989b0b52a4', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 5, 5, 'For I reckon that I am not at all behind the very best apostles.'),
  ('09c84abe-da44-56bd-acdb-e6860d29a9b9', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 6, 6, 'But though I am unskilled in speech, yet I am not unskilled in knowledge. No, in every way we have been revealed to you in all things.'),
  ('366d3d85-e1b0-5706-ad0a-893cde67f747', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 7, 7, 'Or did I commit a sin in humbling myself that you might be exalted, because I preached to you God''s Good News free of charge?'),
  ('5fe028c5-f5aa-59df-ae52-235a5169e1cb', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 8, 8, 'I robbed other assemblies, taking wages from them that I might serve you.'),
  ('614205d0-e586-5f99-a03b-a7973d23b4c8', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 9, 9, 'When I was present with you and was in need, I wasn''t a burden on anyone, for the brothers, when they came from Macedonia, supplied the measure of my need. In everything I kept myself from being burdensome to you, and I will continue to do so.'),
  ('ec87940f-9b3f-5158-af04-9e602451e501', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 10, 10, 'As the truth of Christ is in me, no one will stop me from this boasting in the regions of Achaia.'),
  ('4ced4216-e5ea-54a0-a534-0c6b2cf88f27', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 11, 11, 'Why? Because I don''t love you? God knows.'),
  ('cff80a50-5db2-51c2-ac39-cbe231aa4080', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 12, 12, 'But what I do, that I will do, that I may cut off occasion from them that desire an occasion, that in which they boast, they may be found even as we.'),
  ('4ac20bc0-1722-5e88-a559-b83daf625861', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 13, 13, 'For such men are false apostles, deceitful workers, masquerading as Christ''s apostles.'),
  ('1851f89c-d794-5043-a910-9a888db6e3ce', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 14, 14, 'And no wonder, for even Satan masquerades as an angel of light.'),
  ('64ac112b-f9e3-5258-a213-a3b24be79653', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 15, 15, 'It is no great thing therefore if his servants also masquerade as servants of righteousness, whose end will be according to their works.'),
  ('3a5683da-3ba0-5eef-af21-2c3c28b3c7a6', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 16, 16, 'I say again, let no one think me foolish. But if so, yet receive me as foolish, that I also may boast a little.'),
  ('dd4f1eb5-5485-5df9-a954-b57ee228cd7b', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 17, 17, 'That which I speak, I don''t speak according to the Lord, but as in foolishness, in this confidence of boasting.'),
  ('ade387f0-96cf-56ae-aa74-bc6fc202eab2', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 18, 18, 'Seeing that many boast after the flesh, I will also boast.'),
  ('8d8b6a5d-63f3-5717-a2f2-5239eaf4842b', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 19, 19, 'For you bear with the foolish gladly, being wise.'),
  ('8b17e8a1-9d11-5360-a745-af3877791920', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 20, 20, 'For you bear with a man, if he brings you into bondage, if he devours you, if he takes you captive, if he exalts himself, if he strikes you on the face.'),
  ('880d68e2-b3cb-52b2-a3c0-cb93e3fe5289', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 21, 21, 'I speak by way of disparagement, as though we had been weak. Yet however any is bold (I speak in foolishness), I am bold also.'),
  ('7a58c796-8d60-5d8e-a6bf-4823a99cd855', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 22, 22, 'Are they Hebrews? So am I. Are they Israelites? So am I. Are they the seed of Abraham? So am I.'),
  ('4fbf191f-6173-5e2b-aeb7-a9b9cd7e2a43', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 23, 23, 'Are they servants of Christ? (I speak as one beside himself) I am more so; in labors more abundantly, in prisons more abundantly, in stripes above measure, in deaths often.'),
  ('a9f7e2c4-ae99-5a89-a633-0da132e20136', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 24, 24, 'Five times from the Jews I received forty stripes minus one.'),
  ('5e5202ce-73ce-5a8f-a7e5-abcc4a57434e', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 25, 25, 'Three times I was beaten with rods. Once I was stoned. Three times I suffered shipwreck. I have been a night and a day in the deep.'),
  ('db17897f-ab34-52a0-a1b5-9c7b1e5ce321', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 26, 26, 'I have been in travels often, perils of rivers, perils of robbers, perils from my countrymen, perils from the Gentiles, perils in the city, perils in the wilderness, perils in the sea, perils among false brothers;'),
  ('d89b4fb5-6262-5a65-a5a3-53450b9d8e4a', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 27, 27, 'in labor and travail, in watchings often, in hunger and thirst, in fastings often, and in cold and nakedness.'),
  ('51fc65b5-0149-5738-a486-12e3ad349f97', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 28, 28, 'Besides those things that are outside, there is that which presses on me daily, anxiety for all the assemblies.'),
  ('8e2bf92e-9564-5f42-afe5-32f12157071f', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 29, 29, 'Who is weak, and I am not weak? Who is caused to stumble, and I don''t burn with indignation?'),
  ('d0be94ac-a634-5fe6-a9d3-9ac021431622', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 30, 30, 'If I must boast, I will boast of the things that concern my weakness.'),
  ('3b693b06-770a-5379-a1e8-ea8523f0704a', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 31, 31, 'The God and Father of the Lord Jesus Christ, he who is blessed forevermore, knows that I don''t lie.'),
  ('67fdc982-d1e5-542b-af38-420ec7fa76b5', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 32, 32, 'In Damascus the governor under King Aretas guarded the city of the Damascenes desiring to arrest me.'),
  ('9113f122-472e-5719-af34-75568568ab78', '8b258802-4a5d-5475-a42c-2598b5e718ea', NULL, 33, 33, 'Through a window I was let down in a basket by the wall, and escaped his hands.'),
  ('2d30383c-b8b1-583a-a2a9-bb45a8ab8bbb', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 1, 1, 'It is doubtless not profitable for me to boast. For I will come to visions and revelations of the Lord.'),
  ('944a3169-17b6-5ecd-a46e-8db123882f27', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 2, 2, 'I know a man in Christ, fourteen years ago (whether in the body, I don''t know, or whether out of the body, I don''t know; God knows), such a one caught up into the third heaven.'),
  ('178caf08-2da5-5a50-a39e-f1740c50b6c7', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 3, 3, 'I know such a man (whether in the body, or outside of the body, I don''t know; God knows),'),
  ('b925622d-505a-5378-a58c-52180ddf8542', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 4, 4, 'how he was caught up into Paradise, and heard unspeakable words, which it is not lawful for a man to utter.'),
  ('e0f603ba-5927-546d-a0a8-478d00555937', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 5, 5, 'On behalf of such a one I will boast, but on my own behalf I will not boast, except in my weaknesses.'),
  ('a9c90560-6f2d-5c8f-a307-dc3adf76df3c', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 6, 6, 'For if I would desire to boast, I will not be foolish; for I will speak the truth. But I refrain, so that no man may think more of me than that which he sees in me, or hears from me.'),
  ('0e31918a-005e-5293-a734-097678f1c096', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 7, 7, 'By reason of the exceeding greatness of the revelations, that I should not be exalted excessively, there was given to me a thorn in the flesh, a messenger of Satan to torment me, that I should not be exalted excessively.'),
  ('2a6957f8-5658-5d55-a296-23f73b316df7', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 8, 8, 'Concerning this thing, I begged the Lord three times that it might depart from me.'),
  ('efd3180c-6cea-50ff-a76f-92aa18cbdc59', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 9, 9, 'He has said to me, "My grace is sufficient for you, for my power is made perfect in weakness." Most gladly therefore I will rather glory in my weaknesses, that the power of Christ may rest on me.'),
  ('e2088968-5d13-5737-ad9a-5681d759a521', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 10, 10, 'Therefore I take pleasure in weaknesses, in injuries, in necessities, in persecutions, in distresses, for Christ''s sake. For when I am weak, then am I strong.'),
  ('01d7e32b-9054-5448-ad64-22e9a9e485e4', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 11, 11, 'I have become foolish in boasting. You compelled me, for I ought to have been commended by you, for in nothing was I inferior to the very best apostles, though I am nothing.'),
  ('5aaedc7c-5404-5d2c-a7b3-048566fb0e87', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 12, 12, 'Truly the signs of an apostle were worked among you in all patience, in signs and wonders and mighty works.'),
  ('f527be23-448e-5b41-a9e4-381dee4c9c63', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 13, 13, 'For what is there in which you were made inferior to the rest of the assemblies, unless it is that I myself was not a burden to you? Forgive me this wrong.'),
  ('edff5b26-4beb-574d-aaaa-c700de0df431', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 14, 14, 'Behold, this is the third time I am ready to come to you, and I will not be a burden to you; for I seek not your possessions, but you. For the children ought not to save up for the parents, but the parents for the children.'),
  ('694e9b70-ae61-55d9-a0bd-f3b04f161157', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 15, 15, 'I will most gladly spend and be spent for your souls. If I love you more abundantly, am I loved the less?'),
  ('879c6d62-7498-53ca-a23b-7f8e15817f92', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 16, 16, 'But be it so, I did not myself burden you. But, being crafty, I caught you with deception.'),
  ('c9c1852b-a080-5aa8-a5ff-c756320e5572', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 17, 17, 'Did I take advantage of you by anyone of them whom I have sent to you?'),
  ('10e5cc7b-d130-55d1-a481-f3c63fdd48da', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 18, 18, 'I exhorted Titus, and I sent the brother with him. Did Titus take any advantage of you? Didn''t we walk in the same spirit? Didn''t we walk in the same steps?'),
  ('c51708cd-9521-51ba-a437-e0c34429f399', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 19, 19, 'Again, do you think that we are excusing ourselves to you? In the sight of God we speak in Christ. But all things, beloved, are for your edifying.'),
  ('9b531feb-f4ce-510d-a718-6d74fc910907', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 20, 20, 'For I am afraid that by any means, when I come, I might find you not the way I want to, and that I might be found by you as you don''t desire; that by any means there would be strife, jealousy, outbursts of anger, factions, slander, whisperings, proud thoughts, riots;'),
  ('a9660fe6-7cef-54ad-a4d4-048edfa7e568', '41631010-03e3-59ca-ae81-630b4facc30b', NULL, 21, 21, 'that again when I come my God would humble me before you, and I would mourn for many of those who have sinned before now, and not repented of the uncleanness and sexual immorality and lustfulness which they committed.'),
  ('4f5bf4a5-4d50-54cf-a57b-c32c77d9abc7', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 1, 1, 'This is the third time I am coming to you. "At the mouth of two or three witnesses shall every word be established."'),
  ('0777e33f-1d4f-59ef-a31a-0b70c2353d2e', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 2, 2, 'I have said beforehand, and I do say beforehand, as when I was present the second time, so now, being absent, I write to those who have sinned before now, and to all the rest, that, if I come again, I will not spare;'),
  ('b0ba3f32-b7de-58ad-a854-12aa93bf4b90', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 3, 3, 'seeing that you seek a proof of Christ who speaks in me; who toward you is not weak, but is powerful in you.'),
  ('7b266f56-8dad-5180-ae65-2ca13deceea7', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 4, 4, 'For he was crucified through weakness, yet he lives through the power of God. For we also are weak in him, but we will live with him through the power of God toward you.'),
  ('0e76451a-a8fb-5b5a-a95b-6f57ad1a1f16', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 5, 5, 'Test your own selves, whether you are in the faith. Test your own selves. Or don''t you know as to your own selves, that Jesus Christ is in you?--unless indeed you are disqualified.'),
  ('7478734c-0942-5811-a11c-b84e5e537c0b', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 6, 6, 'But I hope that you will know that we aren''t disqualified.'),
  ('5ee18c08-6141-5cf4-a9d7-beb5c96d9af1', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 7, 7, 'Now I pray to God that you do no evil; not that we may appear approved, but that you may do that which is honorable, though we are as reprobate.'),
  ('717b2990-a4d9-5423-a7fa-6aae32bfdb51', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 8, 8, 'For we can do nothing against the truth, but for the truth.'),
  ('5883db47-2085-5974-ad57-887a520e162e', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 9, 9, 'For we rejoice when we are weak and you are strong. And this we also pray for, even your perfecting.'),
  ('7e28115c-d5c9-5b02-a4bb-ae8ad2fa1f5d', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 10, 10, 'For this cause I write these things while absent, that I may not deal sharply when present, according to the authority which the Lord gave me for building up, and not for tearing down.'),
  ('db7e0ab0-8aa2-549e-a890-ecc035fdfc42', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 11, 11, 'Finally, brothers, rejoice. Be perfected, be comforted, be of the same mind, live in peace, and the God of love and peace will be with you.'),
  ('5ad2d007-546d-5823-aba3-918d2444f8cb', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 12, 12, 'Greet one another with a holy kiss.'),
  ('8b39b501-c148-5ff1-a4ec-1b23697cd934', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 13, 13, 'All the saints greet you.'),
  ('8c6647a5-1cd5-5e47-abce-ce4cdcc7c8c6', '8eed00e6-21f7-5c52-a4d3-a04d2de39242', NULL, 14, 14, 'The grace of the Lord Jesus Christ, the love of God, and the fellowship of the Holy Spirit, be with you all. Amen.'),
  ('c4d89ff4-64a4-548b-a51b-5c9b6dfbcb6e', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 1, 1, 'Paul, an apostle (not from men, neither through man, but through Jesus Christ, and God the Father, who raised him from the dead),'),
  ('24ba9d83-544d-5ade-a67d-6bc5ce73e729', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 2, 2, 'and all the brothers who are with me, to the assemblies of Galatia:'),
  ('8987705b-b101-5857-adc9-0118de263627', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 3, 3, 'Grace to you and peace from God the Father, and our Lord Jesus Christ,'),
  ('912003b8-b40f-51bc-a12a-289ec91ff66a', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 4, 4, 'who gave himself for our sins, that he might deliver us out of this present evil age, according to the will of our God and Father--'),
  ('d1fe1644-21b7-5481-af74-89dd252f5fdb', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 5, 5, 'to whom be the glory forever and ever. Amen.'),
  ('692b3b75-7a61-58bf-a6b3-c14acb426c29', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 6, 6, 'I marvel that you are so quickly deserting him who called you in the grace of Christ to a different "good news";'),
  ('8a89539d-442b-5e84-a5e7-f6ef340310d0', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 7, 7, 'and there isn''t another "good news." Only there are some who trouble you, and want to pervert the Good News of Christ.'),
  ('eb6d0775-9c25-5e16-a5c1-0a25b11f3996', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 8, 8, 'But even though we, or an angel from heaven, should preach to you any "good news" other than that which we preached to you, let him be cursed.'),
  ('bb231d51-110c-5ce2-a96f-d135ffcaa1dc', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 9, 9, 'As we have said before, so I now say again: if any man preaches to you any "good news" other than that which you received, let him be cursed.'),
  ('b97d198b-b85c-59de-a125-1fd92b6ac32c', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 10, 10, 'For am I now seeking the favor of men, or of God? Or am I striving to please men? For if I were still pleasing men, I wouldn''t be a servant of Christ.'),
  ('bce1fc53-deec-511e-a156-828b85916f18', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 11, 11, 'But I make known to you, brothers, concerning the Good News which was preached by me, that it is not according to man.'),
  ('e0c701a4-4a40-5675-aa6b-b708cf3b1f2f', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 12, 12, 'For neither did I receive it from man, nor was I taught it, but it came to me through revelation of Jesus Christ.'),
  ('2c8b13f0-9ddf-5c74-a3b6-de8f9207a308', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 13, 13, 'For you have heard of my way of living in time past in the Jews'' religion, how that beyond measure I persecuted the assembly of God, and ravaged it.'),
  ('c1b147ff-a5a3-58f4-a0bf-8094135d84c6', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 14, 14, 'I advanced in the Jews'' religion beyond many of my own age among my countrymen, being more exceedingly zealous for the traditions of my fathers.'),
  ('1bf2c6d3-6714-539b-a5ff-84d1832ad299', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 15, 15, 'But when it was the good pleasure of God, who separated me from my mother''s womb, and called me through his grace,'),
  ('5d1c6daf-1afd-55a7-a22c-ce4b4043010c', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 16, 16, 'to reveal his Son in me, that I might preach him among the Gentiles, I didn''t immediately confer with flesh and blood,'),
  ('71004501-172b-53ec-afbf-e85211d12078', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 17, 17, 'nor did I go up to Jerusalem to those who were apostles before me, but I went away into Arabia. Then I returned to Damascus.'),
  ('e470a513-9247-5c48-afb4-6fceb79a123a', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 18, 18, 'Then after three years I went up to Jerusalem to visit Peter, and stayed with him fifteen days.'),
  ('f7c2a2e2-65f6-5a19-ab5c-7dd2d5e36422', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 19, 19, 'But of the other apostles I saw no one, except James, the Lord''s brother.'),
  ('52efa51c-d82a-5165-aa73-b4f49856e0cc', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 20, 20, 'Now about the things which I write to you, behold, before God, I''m not lying.'),
  ('efadb977-888f-5e0e-a9dc-69b128b21237', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 21, 21, 'Then I came to the regions of Syria and Cilicia.'),
  ('40c83cb6-0355-5112-a592-c5fea591365f', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 22, 22, 'I was still unknown by face to the assemblies of Judea which were in Christ,'),
  ('b344ef56-ba6c-5c93-a905-7ab11a6891cb', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 23, 23, 'but they only heard: "He who once persecuted us now preaches the faith that he once tried to destroy."'),
  ('251d67bc-5384-5756-a6c7-2a8540938e28', 'c17951f7-53fe-5c94-ab6a-df062f5cce2d', NULL, 24, 24, 'And they glorified God in me.'),
  ('47e7005e-9fa7-51d0-a109-752ceccf4a5b', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 1, 1, 'Then after a period of fourteen years I went up again to Jerusalem with Barnabas, taking Titus also with me.'),
  ('965c0ded-377a-57c9-af4b-0badb1d06c6d', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 2, 2, 'I went up by revelation, and I laid before them the Good News which I preach among the Gentiles, but privately before those who were respected, for fear that I might be running, or had run, in vain.'),
  ('cb45e29e-eadb-51cc-a6b5-ddb21a94bd3a', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 3, 3, 'But not even Titus, who was with me, being a Greek, was compelled to be circumcised.'),
  ('d14923f2-23e4-50c7-af8a-4bde96da37dd', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 4, 4, 'This was because of the false brothers secretly brought in, who stole in to spy out our liberty which we have in Christ Jesus, that they might bring us into bondage;'),
  ('5e70f201-dd81-57f1-aaeb-679e7d6bd121', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 5, 5, 'to whom we gave no place in the way of subjection, not for an hour, that the truth of the Good News might continue with you.'),
  ('3f3ca2c1-836e-570a-a543-fd3303f2512d', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 6, 6, 'But from those who were reputed to be important (whatever they were, it makes no difference to me; God doesn''t show partiality to man)--they, I say, who were respected imparted nothing to me,'),
  ('6b4f9cab-7a2e-528a-ad3f-6b7708a9a970', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 7, 7, 'but to the contrary, when they saw that I had been entrusted with the Good News for the uncircumcision, even as Peter with the Good News for the circumcision'),
  ('7ba9dcec-1de0-565b-af45-f9aa6d2f7eb1', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 8, 8, '(for he who appointed Peter to the apostleship of the circumcision appointed me also to the Gentiles);'),
  ('23c813fd-c924-57ef-a44c-ba3c35500122', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 9, 9, 'and when they perceived the grace that was given to me, James and Cephas and John, they who were reputed to be pillars, gave to me and Barnabas the right hand of fellowship, that we should go to the Gentiles, and they to the circumcision.'),
  ('38b78dad-ca49-5293-a110-79a271866ea7', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 10, 10, 'They only asked us to remember the poor--which very thing I was also zealous to do.'),
  ('076d0b65-f658-5bb3-a84a-c4ece9ee8b5b', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 11, 11, 'But when Peter came to Antioch, I resisted him to his face, because he stood condemned.'),
  ('13902e95-80b2-54d3-a561-ccfd76feb2bd', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 12, 12, 'For before some people came from James, he ate with the Gentiles. But when they came, he drew back and separated himself, fearing those who were of the circumcision.'),
  ('f7771cb0-2819-5e1f-ad59-2b6a7d8b5a71', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 13, 13, 'And the rest of the Jews joined him in his hypocrisy; so that even Barnabas was carried away with their hypocrisy.'),
  ('178be050-1a84-564f-a28f-77e637a0567c', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 14, 14, 'But when I saw that they didn''t walk uprightly according to the truth of the Good News, I said to Peter before them all, "If you, being a Jew, live as the Gentiles do, and not as the Jews do, why do you compel the Gentiles to live as the Jews do?'),
  ('c46eaf6e-1e04-569a-ab41-d5fb9c5613e5', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 15, 15, '"We, being Jews by nature, and not Gentile sinners,'),
  ('a0f95fc8-dcd0-5e96-ac99-8bc86c923f62', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 16, 16, 'yet knowing that a man is not justified by the works of the law but through faith in Jesus Christ, even we believed in Christ Jesus, that we might be justified by faith in Christ, and not by the works of the law, because no flesh will be justified by the works of the law.'),
  ('4f71d02c-d1bd-5b53-a16a-c2035164cfdc', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 17, 17, 'But if, while we sought to be justified in Christ, we ourselves also were found sinners, is Christ a servant of sin? Certainly not!'),
  ('5a60a034-0c20-52ea-abf0-3fe69dda3940', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 18, 18, 'For if I build up again those things which I destroyed, I prove myself a law-breaker.'),
  ('1dad2b83-c9d6-5c10-a6a1-3d81ee125269', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 19, 19, 'For I, through the law, died to the law, that I might live to God.'),
  ('d00fcb69-ac86-5ea7-a469-9ec51d244ddb', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 20, 20, 'I have been crucified with Christ, and it is no longer I that live, but Christ living in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me, and gave himself up for me.'),
  ('e60bb9f9-f1fa-58e2-a9bf-75ccc4e66e1a', 'd8540749-c766-5a94-acff-75a4cb903f4d', NULL, 21, 21, 'I don''t make void the grace of God. For if righteousness is through the law, then Christ died for nothing!"'),
  ('68c9dd4b-b0f6-5df2-a68e-5f4fbfa25ff1', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 1, 1, 'Foolish Galatians, who has bewitched you not to obey the truth, before whose eyes Jesus Christ was openly set forth among you as crucified?'),
  ('5585f22f-7b1f-5863-adcb-587d8fcbb745', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 2, 2, 'I just want to learn this from you. Did you receive the Spirit by the works of the law, or by hearing of faith?'),
  ('02951258-a6a2-5af1-ab92-0ade166ce347', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 3, 3, 'Are you so foolish? Having begun in the Spirit, are you now completed in the flesh?'),
  ('341015f5-f8d7-51da-a1cc-d4d4b642d475', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 4, 4, 'Did you suffer so many things in vain, if it is indeed in vain?'),
  ('9d604ce2-fbcb-5c76-a618-b057e82afb3a', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 5, 5, 'He therefore who supplies the Spirit to you, and works miracles among you, does he do it by the works of the law, or by hearing of faith?'),
  ('4e7a8aad-54c8-5f94-a602-feaf2c7cadc1', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 6, 6, 'Even as Abraham "believed God, and it was counted to him for righteousness."'),
  ('8717e7cb-256e-597e-a37d-a796ea854e7b', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 7, 7, 'Know therefore that those who are of faith, the same are children of Abraham.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8d21fcd6-0b52-5655-aef5-f8bd0837c659', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 8, 8, 'The Scripture, foreseeing that God would justify the Gentiles by faith, preached the Good News beforehand to Abraham, saying, "In you all the nations will be blessed."'),
  ('82b42799-7892-5257-ad02-173f6a9d7507', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 9, 9, 'So then, those who are of faith are blessed with the faithful Abraham.'),
  ('fcce7338-c546-5413-af47-cffaafc12403', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 10, 10, 'For as many as are of the works of the law are under a curse. For it is written, "Cursed is everyone who doesn''t continue in all things that are written in the book of the law, to do them."'),
  ('5c3b30d6-a417-503a-a6a7-ecb98c207fb9', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 11, 11, 'Now that no man is justified by the law before God is evident, for, "The righteous will live by faith."'),
  ('5a4f989a-5c2d-5fc6-ab59-2ed6e1981605', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 12, 12, 'The law is not of faith, but, "The man who does them will live by them."'),
  ('3c8c91ba-1dc0-5352-abcb-942b675c9963', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 13, 13, 'Christ redeemed us from the curse of the law, having become a curse for us. For it is written, "Cursed is everyone who hangs on a tree,"'),
  ('6a8e6851-972d-5116-a408-4b54f3373638', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 14, 14, 'that the blessing of Abraham might come on the Gentiles through Christ Jesus; that we might receive the promise of the Spirit through faith.'),
  ('acba3273-ecd6-5a59-a2b5-556749f5b7d2', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 15, 15, 'Brothers, speaking of human terms, though it is only a man''s covenant, yet when it has been confirmed, no one makes it void, or adds to it.'),
  ('6bfb81b3-497a-5428-aebf-0917e46b603a', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 16, 16, 'Now the promises were spoken to Abraham and to his seed. He doesn''t say, "To seeds," as of many, but as of one, "To your seed," which is Christ.'),
  ('6c6303d5-012d-5beb-a20b-3eb8abf72445', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 17, 17, 'Now I say this. A covenant confirmed beforehand by God in Christ, the law, which came four hundred thirty years after, does not annul, so as to make the promise of no effect.'),
  ('3bd731ac-5449-5e75-a91e-f1266e34f0f7', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 18, 18, 'For if the inheritance is of the law, it is no more of promise; but God has granted it to Abraham by promise.'),
  ('3290f558-04eb-51c9-a265-a468aa471f5a', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 19, 19, 'What then is the law? It was added because of transgressions, until the seed should come to whom the promise has been made. It was ordained through angels by the hand of a mediator.'),
  ('5e28e934-e67e-5268-ab1f-a647ff92c8ed', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 20, 20, 'Now a mediator is not between one, but God is one.'),
  ('918c163c-8e2c-5c8e-af06-d1d412e4e41e', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 21, 21, 'Is the law then against the promises of God? Certainly not! For if there had been a law given which could make alive, most certainly righteousness would have been of the law.'),
  ('57e8ea1e-fdc0-5ef6-a969-a77ff0b8ad69', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 22, 22, 'But the Scriptures imprisoned all things under sin, that the promise by faith in Jesus Christ might be given to those who believe.'),
  ('bc7755ca-3efd-51cf-a25f-835daf1ca674', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 23, 23, 'But before faith came, we were kept in custody under the law, confined for the faith which should afterwards be revealed.'),
  ('a60b45fa-1e3d-5ca2-acdd-042e0bd6a13c', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 24, 24, 'So that the law has become our tutor to bring us to Christ, that we might be justified by faith.'),
  ('83593dce-6fa0-526e-a094-836fa1a59216', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 25, 25, 'But now that faith has come, we are no longer under a tutor.'),
  ('0ec74989-8fb4-58d3-ab1c-3723229d637a', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 26, 26, 'For you are all children of God, through faith in Christ Jesus.'),
  ('ea424ceb-7bd8-5133-a315-e89f2fae71ae', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 27, 27, 'For as many of you as were baptized into Christ have put on Christ.'),
  ('4de95cfa-f2b9-5797-ac81-aedaacde5ebc', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 28, 28, 'There is neither Jew nor Greek, there is neither slave nor free man, there is neither male nor female; for you are all one in Christ Jesus.'),
  ('b88b98c6-b254-5d20-add8-067ac7b35ddb', '11a8279c-5481-5a8f-a10d-4183f4a077fc', NULL, 29, 29, 'If you are Christ''s, then you are Abraham''s seed and heirs according to promise.'),
  ('8f462ace-50c3-5189-a55d-88afa901261f', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 1, 1, 'But I say that so long as the heir is a child, he is no different from a bondservant, though he is lord of all;'),
  ('96c85ca8-f504-5b65-a5a7-64824c76f8f3', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 2, 2, 'but is under guardians and stewards until the day appointed by the father.'),
  ('035eac50-2951-58c3-a7fc-b1ac57a1b03e', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 3, 3, 'So we also, when we were children, were held in bondage under the elemental principles of the world.'),
  ('bae70c71-15f6-501d-a053-537ccfc35e42', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 4, 4, 'But when the fullness of the time came, God sent out his Son, born to a woman, born under the law,'),
  ('34ff8e62-71b1-5180-a4e6-ef667fdca092', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 5, 5, 'that he might redeem those who were under the law, that we might receive the adoption of children.'),
  ('b7501753-fa94-568b-aacb-2b4e65ef6d29', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 6, 6, 'And because you are children, God sent out the Spirit of his Son into your hearts, crying, "Abba, Father!"'),
  ('ee327c12-9df7-5a52-a5df-bd1a8d63f270', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 7, 7, 'So you are no longer a bondservant, but a son; and if a son, then an heir of God through Christ.'),
  ('39cc556a-0f2b-5556-a4a0-0a9534a9f4c2', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 8, 8, 'However at that time, not knowing God, you were in bondage to those who by nature are not gods.'),
  ('ecb21ac5-d017-5c0a-ab8f-57e7b3aca256', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 9, 9, 'But now that you have come to know God, or rather to be known by God, why do you turn back again to the weak and miserable elemental principles, to which you desire to be in bondage all over again?'),
  ('4385189b-ba95-5f12-ae35-737f5fe7e3de', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 10, 10, 'You observe days, months, seasons, and years.'),
  ('12cfae41-2553-511c-ab9d-d22d164d0d16', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 11, 11, 'I am afraid for you, that I might have wasted my labor for you.'),
  ('e58290db-ad54-577e-a663-1a6f81ac27dd', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 12, 12, 'I beg you, brothers, become as I am, for I also have become as you are. You did me no wrong,'),
  ('5464e6bf-35f3-539c-a0de-ce4d7d393f30', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 13, 13, 'but you know that because of weakness of the flesh I preached the Good News to you the first time.'),
  ('028185a1-d8e7-50a7-a000-a939af8f3b56', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 14, 14, 'That which was a temptation to you in my flesh, you didn''t despise nor reject; but you received me as an angel of God, even as Christ Jesus.'),
  ('3a1fdf86-c8a0-5e51-a01e-7f94d7c073c3', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 15, 15, 'What was the blessing you enjoyed? For I testify to you that, if possible, you would have plucked out your eyes and given them to me.'),
  ('8040c6b4-a9f6-5b62-a426-2d8cf921acd1', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 16, 16, 'So then, have I become your enemy by telling you the truth?'),
  ('69e08c3a-4d16-5de0-a0d4-2c815f9cb937', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 17, 17, 'They zealously seek you in no good way. No, they desire to alienate you, that you may seek them.'),
  ('973f1c98-3977-5360-a3a4-95070686e051', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 18, 18, 'But it is always good to be zealous in a good cause, and not only when I am present with you.'),
  ('3aae26b5-720d-5f06-ac54-e323664a3e3e', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 19, 19, 'My little children, of whom I am again in travail until Christ is formed in you--'),
  ('1dba551c-87db-50fc-a492-1aceb5418360', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 20, 20, 'but I could wish to be present with you now, and to change my tone, for I am perplexed about you.'),
  ('93bbf8e5-527f-5e34-acb1-daeeb0f13783', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 21, 21, 'Tell me, you that desire to be under the law, don''t you listen to the law?'),
  ('300a5920-1593-5abe-afbb-99e0423361d6', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 22, 22, 'For it is written that Abraham had two sons, one by the handmaid, and one by the free woman.'),
  ('ab9881c0-ad75-5909-a447-63ae6df20d81', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 23, 23, 'However, the son by the handmaid was born according to the flesh, but the son by the free woman was born through promise.'),
  ('68c414fd-2af6-5075-aa17-e31244525464', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 24, 24, 'These things contain an allegory, for these are two covenants. One is from Mount Sinai, bearing children to bondage, which is Hagar.'),
  ('242221ee-499b-5416-a163-19f67a533b8d', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 25, 25, 'For this Hagar is Mount Sinai in Arabia, and answers to the Jerusalem that exists now, for she is in bondage with her children.'),
  ('4ed06b67-2450-5e90-a48c-f656c90e0852', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 26, 26, 'But the Jerusalem that is above is free, which is the mother of us all.'),
  ('3d79269c-9312-508f-a25d-cf27c65f77e3', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 27, 27, 'For it is written, "Rejoice, you barren who don''t bear. Break forth and shout, you that don''t travail. For more are the children of the desolate than of her who has a husband."'),
  ('ea93495b-1c90-5a5b-a6ed-e8e06865303c', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 28, 28, 'Now we, brothers, as Isaac was, are children of promise.'),
  ('db7e6ecf-2e33-5c70-a77f-637c8978c828', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 29, 29, 'But as then, he who was born according to the flesh persecuted him who was born according to the Spirit, so also it is now.'),
  ('4487a82d-c79a-575a-a36d-2621802f8167', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 30, 30, 'However what does the Scripture say? "Throw out the handmaid and her son, for the son of the handmaid will not inherit with the son of the free woman."'),
  ('5392cae5-36b0-505e-a0e7-c1c96945a3b4', '16a8f922-1656-59c5-a26e-dedb229eb6b2', NULL, 31, 31, 'So then, brothers, we are not children of a handmaid, but of the free woman.'),
  ('5b073480-62dc-5fe5-a799-f5a8951ceb41', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 1, 1, 'Stand firm therefore in the liberty by which Christ has made us free, and don''t be entangled again with a yoke of bondage.'),
  ('04732806-7b41-5c76-a262-fa7e68d0beee', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 2, 2, 'Behold, I, Paul, tell you that if you receive circumcision, Christ will profit you nothing.'),
  ('40786ba4-0bec-5e30-af36-7fcc8994cae9', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 3, 3, 'Yes, I testify again to every man who receives circumcision, that he is a debtor to do the whole law.'),
  ('687e800a-df46-5a90-ac35-3b1e05c7499e', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 4, 4, 'You are alienated from Christ, you who desire to be justified by the law. You have fallen away from grace.'),
  ('468a1874-aabc-5303-a427-4eab82bb402c', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 5, 5, 'For we, through the Spirit, by faith wait for the hope of righteousness.'),
  ('61789e04-3af2-548f-a0fe-0528386f2826', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 6, 6, 'For in Christ Jesus neither circumcision amounts to anything, nor uncircumcision, but faith working through love.'),
  ('9df9d847-e5ef-5114-a926-06937c6c902d', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 7, 7, 'You were running well! Who interfered with you that you should not obey the truth?'),
  ('ffb16484-39b5-5b97-a142-f35422c6b80a', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 8, 8, 'This persuasion is not from him who calls you.'),
  ('4670aab2-058c-56f8-acbe-376c87f81c0e', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 9, 9, 'A little yeast grows through the whole lump.'),
  ('ef2c9197-fc8d-5e65-aa35-516aaf8170e0', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 10, 10, 'I have confidence toward you in the Lord that you will think no other way. But he who troubles you will bear his judgment, whoever he is.'),
  ('1cafcf0f-5d5e-56d0-a89c-4d3c83e119e3', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 11, 11, 'But I, brothers, if I still preach circumcision, why am I still persecuted? Then the stumbling block of the cross has been removed.'),
  ('325c9cce-e79f-5767-ac7a-d3e796612039', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 12, 12, 'I wish that those who disturb you would cut themselves off.'),
  ('64eecd60-2cc9-5f80-aed2-5159bcdb526f', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 13, 13, 'For you, brothers, were called for freedom. Only don''t use your freedom for gain to the flesh, but through love be servants to one another.'),
  ('4f475fe1-611c-5293-aca8-4a4ffded76eb', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 14, 14, 'For the whole law is fulfilled in one word, in this: "You shall love your neighbor as yourself."'),
  ('9b180ec0-a842-583d-a292-b133f97e443e', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 15, 15, 'But if you bite and devour one another, be careful that you don''t consume one another.'),
  ('7cb522d7-47e1-5417-a851-623501357db8', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 16, 16, 'But I say, walk by the Spirit, and you won''t fulfill the lust of the flesh.'),
  ('e49346dd-2bcd-551f-a4ce-7820f0c991db', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 17, 17, 'For the flesh lusts against the Spirit, and the Spirit against the flesh; and these are contrary to one another, that you may not do the things that you desire.'),
  ('e1dd5db3-57c3-5cc6-af6a-74ad9811f3c9', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 18, 18, 'But if you are led by the Spirit, you are not under the law.'),
  ('aadfc76c-40c9-5faa-a867-cae60d7c3dbc', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 19, 19, 'Now the works of the flesh are obvious, which are: adultery, sexual immorality, uncleanness, lustfulness,'),
  ('5cd55fb4-0361-59b0-a608-99a965d618be', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 20, 20, 'idolatry, sorcery, hatred, strife, jealousies, outbursts of anger, rivalries, divisions, heresies,'),
  ('7da2562b-2f7c-55cd-abd0-b1fd23682a76', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 21, 21, 'envyings, murders, drunkenness, orgies, and things like these; of which I forewarn you, even as I also forewarned you, that those who practice such things will not inherit the Kingdom of God.'),
  ('de2e6886-3531-561a-ac77-826ee666713b', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 22, 22, 'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith,'),
  ('99fcf681-7dbc-535a-a467-e14f02fbab91', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 23, 23, 'gentleness, and self-control. Against such things there is no law.'),
  ('8e44fa55-1f0d-5756-a2aa-c073d206c664', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 24, 24, 'Those who belong to Christ have crucified the flesh with its passions and lusts.'),
  ('f1c2dfdb-166e-55e4-ad3c-469f7407ba7f', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 25, 25, 'If we live by the Spirit, let''s also walk by the Spirit.'),
  ('1fc761de-b311-51d8-a6a6-6b88354d6ffb', '39c70941-d5b0-53dc-a337-d2d8ef2ba905', NULL, 26, 26, 'Let''s not become conceited, provoking one another, and envying one another.'),
  ('d2451221-d61d-59ea-a15a-0e0b9b3d116f', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 1, 1, 'Brothers, even if a man is caught in some fault, you who are spiritual must restore such a one in a spirit of gentleness; looking to yourself so that you also aren''t tempted.'),
  ('bd9bfba9-bb52-5007-aa77-47e6c034ce80', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 2, 2, 'Bear one another''s burdens, and so fulfill the law of Christ.'),
  ('78cf9239-919e-5946-a1c3-58baf5cef3c1', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 3, 3, 'For if a man thinks himself to be something when he is nothing, he deceives himself.'),
  ('ba0eeaec-e3eb-51b4-ae03-3049b64d8f53', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 4, 4, 'But let each man test his own work, and then he will take pride in himself and not in his neighbor.'),
  ('0b6e2227-2415-54f7-a6b5-4fc276bb27ae', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 5, 5, 'For each man will bear his own burden.'),
  ('1f9a5cfc-773e-517a-a0f7-39a5845f5172', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 6, 6, 'But let him who is taught in the word share all good things with him who teaches.'),
  ('d107ed95-9908-59c2-ac7d-4451564df225', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 7, 7, 'Don''t be deceived. God is not mocked, for whatever a man sows, that he will also reap.'),
  ('00c92fe7-42cc-5f85-af8d-ca82ca1a8372', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 8, 8, 'For he who sows to his own flesh will from the flesh reap corruption. But he who sows to the Spirit will from the Spirit reap eternal life.'),
  ('61075ea3-6f8e-5a19-a839-e46902fd5217', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 9, 9, 'Let us not be weary in doing good, for we will reap in due season, if we don''t give up.'),
  ('a08e73b6-39aa-5103-ad2b-74ce8f53e0ef', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 10, 10, 'So then, as we have opportunity, let''s do what is good toward all men, and especially toward those who are of the household of the faith.'),
  ('7406b18c-db3c-5d58-a78e-70622deff22a', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 11, 11, 'See with what large letters I write to you with my own hand.'),
  ('98c57ca8-f6b6-55a2-a9b7-d70c140e992a', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 12, 12, 'As many as desire to look good in the flesh, they compel you to be circumcised; only that they may not be persecuted for the cross of Christ.'),
  ('6e2a983c-6d2f-5fa7-ab9f-0f6b35d91c5c', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 13, 13, 'For even they who receive circumcision don''t keep the law themselves, but they desire to have you circumcised, that they may boast in your flesh.'),
  ('2df1f0e9-b90d-54d0-a0ce-c5bed25be0c6', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 14, 14, 'But far be it from me to boast, except in the cross of our Lord Jesus Christ, through which the world has been crucified to me, and I to the world.'),
  ('c793faa0-ab6f-5678-a266-579bedfc318d', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 15, 15, 'For in Christ Jesus neither is circumcision anything, nor uncircumcision, but a new creation.'),
  ('3e443870-7012-522f-a86d-9d59f8299b31', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 16, 16, 'As many as walk by this rule, peace and mercy be on them, and on God''s Israel.'),
  ('4d3f4b37-a5f2-58b3-a829-fe15f3ba6d5e', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 17, 17, 'From now on, let no one cause me any trouble, for I bear the marks of the Lord Jesus branded on my body.'),
  ('2ca3b534-dd97-5843-a682-70769cf09d39', '19bcf10a-f90a-5eb9-a575-40038555d0fc', NULL, 18, 18, 'The grace of our Lord Jesus Christ be with your spirit, brothers. Amen.'),
  ('2be902d2-a92c-586c-a50b-0c4d43a2207f', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 1, 1, 'Paul, an apostle of Christ Jesus through the will of God, to the saints who are at Ephesus, and the faithful in Christ Jesus:'),
  ('b706fed6-a5d2-5fe0-a1da-e14f0133606d', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 2, 2, 'Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('0e7a84c3-cb32-5794-a376-af2e931148f6', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 3, 3, 'Blessed be the God and Father of our Lord Jesus Christ, who has blessed us with every spiritual blessing in the heavenly places in Christ;'),
  ('476dcd9c-cb51-5f86-ab89-5e367b91ab66', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 4, 4, 'even as he chose us in him before the foundation of the world, that we would be holy and without blemish before him in love;'),
  ('6b747e27-a397-5026-ac2e-32078277bc8b', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 5, 5, 'having predestined us for adoption as children through Jesus Christ to himself, according to the good pleasure of his desire,'),
  ('f6789480-962f-56c9-ab9e-675e623d1b1f', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 6, 6, 'to the praise of the glory of his grace, by which he freely bestowed favor on us in the Beloved,'),
  ('0b54f9b1-fa51-58c3-a53a-07fe0116b002', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 7, 7, 'in whom we have our redemption through his blood, the forgiveness of our trespasses, according to the riches of his grace,'),
  ('dfcb7509-9cd7-590f-a976-ef9146e1d85f', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 8, 8, 'which he made to abound toward us in all wisdom and prudence,'),
  ('0049358c-243f-561f-a868-10434ddfce2f', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 9, 9, 'making known to us the mystery of his will, according to his good pleasure which he purposed in him'),
  ('4e3cb687-caa9-578a-a682-1bf0206cca8c', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 10, 10, 'to an administration of the fullness of the times, to sum up all things in Christ, the things in the heavens, and the things on the earth, in him;'),
  ('8edb7e34-c763-5733-aca5-0ad5d198835b', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 11, 11, 'in whom also we were assigned an inheritance, having been foreordained according to the purpose of him who works all things after the counsel of his will;'),
  ('8f45f627-f07a-5960-a9d2-bd6ab30dfa6c', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 12, 12, 'to the end that we should be to the praise of his glory, we who had before hoped in Christ:'),
  ('7944d93f-b891-54e2-a010-7228a42949b7', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 13, 13, 'in whom you also, having heard the word of the truth, the Good News of your salvation--in whom, having also believed, you were sealed with the Holy Spirit of promise,'),
  ('93d3712e-9c89-542b-a121-8520b19bfaf9', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 14, 14, 'who is a pledge of our inheritance, to the redemption of God''s own possession, to the praise of his glory.'),
  ('81936521-22e9-5c5d-af90-c8356d4a2d0b', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 15, 15, 'For this cause I also, having heard of the faith in the Lord Jesus which is among you, and the love which you have toward all the saints,'),
  ('5fed66f8-c58c-559e-a91f-349e12a970b6', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 16, 16, 'don''t cease to give thanks for you, making mention of you in my prayers,'),
  ('c399fb44-fccb-5242-a04c-217c47298d76', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 17, 17, 'that the God of our Lord Jesus Christ, the Father of glory, may give to you a spirit of wisdom and revelation in the knowledge of him;'),
  ('302a97a6-bdd7-5f43-a5b5-f0b876d3c812', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 18, 18, 'having the eyes of your hearts enlightened, that you may know what is the hope of his calling, and what are the riches of the glory of his inheritance in the saints,'),
  ('ea202307-6b65-5624-a6fd-9115383dfb3a', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 19, 19, 'and what is the exceeding greatness of his power toward us who believe, according to that working of the strength of his might'),
  ('909a33be-ab30-5de8-a1e5-6b6d600987ae', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 20, 20, 'which he worked in Christ, when he raised him from the dead, and made him to sit at his right hand in the heavenly places,'),
  ('924b1ee8-c86c-57f5-aa1e-b59cc838f11f', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 21, 21, 'far above all rule, and authority, and power, and dominion, and every name that is named, not only in this age, but also in that which is to come.'),
  ('2ec11d79-aa1d-5130-aebb-f31935dbbb67', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 22, 22, 'He put all things in subjection under his feet, and gave him to be head over all things for the assembly,'),
  ('c24a0cfb-8f82-57aa-a9b5-2fa189353f00', '27561252-eb2b-55c0-a25a-297e8fb2c000', NULL, 23, 23, 'which is his body, the fullness of him who fills all in all.'),
  ('a04aea0d-1c8c-5046-a502-48947e62cbae', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 1, 1, 'You were made alive when you were dead in transgressions and sins,'),
  ('a9ea1d5f-2f8d-50ad-ac7e-0d206d2295e2', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 2, 2, 'in which you once walked according to the course of this world, according to the prince of the power of the air, the spirit who now works in the children of disobedience;'),
  ('bcca2876-1f40-5ec9-a749-bc60c54a1130', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 3, 3, 'among whom we also all once lived in the lust of our flesh, doing the desires of the flesh and of the mind, and were by nature children of wrath, even as the rest.'),
  ('0c3a7aa5-3463-51d5-a704-6e69e89c4e1f', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 4, 4, 'But God, being rich in mercy, for his great love with which he loved us,'),
  ('8062179e-8d26-581a-a21f-c55881ae5684', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 5, 5, 'even when we were dead through our trespasses, made us alive together with Christ (by grace you have been saved),'),
  ('2ee49fda-f9ff-5520-ab5f-718774a1855b', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 6, 6, 'and raised us up with him, and made us to sit with him in the heavenly places in Christ Jesus,'),
  ('431c6f92-5615-5ae1-a1c9-a1e1e2f47d7d', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 7, 7, 'that in the ages to come he might show the exceeding riches of his grace in kindness toward us in Christ Jesus;'),
  ('c9c331af-129b-508e-a73a-5c55f96e146e', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 8, 8, 'for by grace you have been saved through faith, and that not of yourselves; it is the gift of God,'),
  ('4469b878-f616-5489-a8c4-b22dfdae2461', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 9, 9, 'not of works, that no one would boast.'),
  ('b69c9fd6-81c3-56bd-ad9f-c8b02189c201', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 10, 10, 'For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.'),
  ('450495a3-d2de-5121-a4fb-c38c641400b6', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 11, 11, 'Therefore remember that once you, the Gentiles in the flesh, who are called "uncircumcision" by that which is called "circumcision," (in the flesh, made by hands);'),
  ('da98beaa-b5a2-5f28-ae93-f68136327794', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 12, 12, 'that you were at that time separate from Christ, alienated from the commonwealth of Israel, and strangers from the covenants of the promise, having no hope and without God in the world.'),
  ('3bf7af95-1073-5659-afdf-a2886d7e9199', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 13, 13, 'But now in Christ Jesus you who once were far off are made near in the blood of Christ.'),
  ('3f689b7f-9699-5649-a379-2a5538c1ec76', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 14, 14, 'For he is our peace, who made both one, and broke down the middle wall of partition,'),
  ('7f5bd4cf-bb8f-5483-a306-25e80f8ed794', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 15, 15, 'having abolished in the flesh the hostility, the law of commandments contained in ordinances, that he might create in himself one new man of the two, making peace;'),
  ('688716cb-84dc-539e-a161-bef6fe085f3d', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 16, 16, 'and might reconcile them both in one body to God through the cross, having killed the hostility thereby.'),
  ('8e6b2413-c30d-57fa-a145-6f8c280b59e0', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 17, 17, 'He came and preached peace to you who were far off and to those who were near.'),
  ('cd600455-77e9-541f-a35c-0f4b7ac8aeae', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 18, 18, 'For through him we both have our access in one Spirit to the Father.'),
  ('5083b90d-341d-5f01-a020-e99ccfc171a1', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 19, 19, 'So then you are no longer strangers and foreigners, but you are fellow citizens with the saints, and of the household of God,'),
  ('a0bae8b8-918b-5bd1-a183-5ac0dcbeabd0', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 20, 20, 'being built on the foundation of the apostles and prophets, Christ Jesus himself being the chief cornerstone;'),
  ('486052de-8473-5bc7-a08a-3749734781cd', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 21, 21, 'in whom the whole building, fitted together, grows into a holy temple in the Lord;'),
  ('595ec0ef-939d-5ac3-a13f-deb329a9e93a', 'ebdb2ef8-72f4-5c7a-ac65-4f0651ae862e', NULL, 22, 22, 'in whom you also are built together for a habitation of God in the Spirit.'),
  ('8131c181-befe-5831-a8d1-b860c34542e9', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 1, 1, 'For this cause I, Paul, am the prisoner of Christ Jesus on behalf of you Gentiles,'),
  ('38662afe-8627-5767-a2c3-c455366d844b', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 2, 2, 'if it is so that you have heard of the administration of that grace of God which was given me toward you;'),
  ('c5dd279f-4e4f-534c-a240-1111fb8421ba', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 3, 3, 'how that by revelation the mystery was made known to me, as I wrote before in few words,'),
  ('5cff2869-bb9c-597e-ab2e-7f5ec0c9daeb', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 4, 4, 'by which, when you read, you can perceive my understanding in the mystery of Christ;'),
  ('a2e627f0-ebdd-5bf4-a64d-2882177633cc', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 5, 5, 'which in other generations was not made known to the children of men, as it has now been revealed to his holy apostles and prophets in the Spirit;'),
  ('d97b4c0d-e9c9-50b5-a9b5-3f87b46864e5', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 6, 6, 'that the Gentiles are fellow heirs, and fellow members of the body, and fellow partakers of his promise in Christ Jesus through the Good News,'),
  ('ef0977c1-cfc8-5bd3-a44d-5fdfb3ba3e6d', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 7, 7, 'of which I was made a servant, according to the gift of that grace of God which was given me according to the working of his power.'),
  ('ab85c7e7-effb-54d4-a0f5-7f65f93787e2', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 8, 8, 'To me, the very least of all saints, was this grace given, to preach to the Gentiles the unsearchable riches of Christ,'),
  ('1f9306ab-f8c3-506b-a3e6-7167eeeb3a87', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 9, 9, 'and to make all men see what is the administration of the mystery which for ages has been hidden in God, who created all things through Jesus Christ;'),
  ('61fc8a7b-4868-5456-a94f-cd5814ceb109', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 10, 10, 'to the intent that now through the assembly the manifold wisdom of God might be made known to the principalities and the powers in the heavenly places,'),
  ('a1cfa292-5e1d-5332-a9c9-0a88d01f5b2c', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 11, 11, 'according to the eternal purpose which he purposed in Christ Jesus our Lord;'),
  ('43821a9d-c676-5d45-afc8-4d0531ef82e3', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 12, 12, 'in whom we have boldness and access in confidence through our faith in him.'),
  ('45158b95-6d51-51e7-a683-3451d2e3f90a', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 13, 13, 'Therefore I ask that you may not lose heart at my troubles for you, which are your glory.'),
  ('779447c1-67e8-5bb0-ae9e-9ef0f6f7a313', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 14, 14, 'For this cause, I bow my knees to the Father of our Lord Jesus Christ,'),
  ('e44dabd5-91a9-58dd-a2f8-7148bae2bf6c', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 15, 15, 'from whom every family in heaven and on earth is named,'),
  ('f722b226-baa0-58b7-a5d3-252116d02f47', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 16, 16, 'that he would grant you, according to the riches of his glory, that you may be strengthened with power through his Spirit in the inward man;'),
  ('0273c865-59e9-5129-a484-81e89e70605b', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 17, 17, 'that Christ may dwell in your hearts through faith; to the end that you, being rooted and grounded in love,'),
  ('c4b4f91c-db48-51ef-a40a-3dbdbfeb3b97', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 18, 18, 'may be strengthened to comprehend with all the saints what is the breadth and length and height and depth,'),
  ('994f8121-064a-5b39-aac8-2774f662376c', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 19, 19, 'and to know Christ''s love which surpasses knowledge, that you may be filled with all the fullness of God.'),
  ('79b0d559-80ee-5db0-adad-e21c181d5774', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 20, 20, 'Now to him who is able to do exceedingly abundantly above all that we ask or think, according to the power that works in us,'),
  ('abcbeeca-0879-524a-a290-e3c7c1fbba3f', '4bc48676-b8ab-5fc6-af96-feebb3be7966', NULL, 21, 21, 'to him be the glory in the assembly and in Christ Jesus to all generations forever and ever. Amen.'),
  ('519a418a-c976-5afa-a502-817d1d7fffb3', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 1, 1, 'I therefore, the prisoner in the Lord, beg you to walk worthily of the calling with which you were called,'),
  ('fc9727c2-b77d-5017-a4bb-e400b15b0ff4', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 2, 2, 'with all lowliness and humility, with patience, bearing with one another in love;'),
  ('82d521d1-dec9-54a1-ad08-a7eda59fcc2b', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 3, 3, 'being eager to keep the unity of the Spirit in the bond of peace.'),
  ('c1c27626-ced4-5211-aac5-72bd4dc5efa4', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 4, 4, 'There is one body, and one Spirit, even as you also were called in one hope of your calling;'),
  ('50bc06b4-3575-587f-a70d-8176f68bbacc', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 5, 5, 'one Lord, one faith, one baptism,'),
  ('a8dd4fb7-e2db-552b-a0ae-9a349643d23d', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 6, 6, 'one God and Father of all, who is over all, and through all, and in us all.'),
  ('c545ba2e-27b9-50b5-a6ce-3eef6d9d7eaa', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 7, 7, 'But to each one of us was the grace given according to the measure of the gift of Christ.'),
  ('6debdd92-f827-524d-aa3f-64c7cc77d202', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 8, 8, 'Therefore he says, "When he ascended on high, he led captivity captive, and gave gifts to men."'),
  ('f32850db-2054-5f25-a6ce-96eaaa02586d', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 9, 9, 'Now this, "He ascended," what is it but that he also first descended into the lower parts of the earth?'),
  ('c6845166-0c83-5894-ad01-502b0c52d738', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 10, 10, 'He who descended is the one who also ascended far above all the heavens, that he might fill all things.'),
  ('7879b293-e031-5463-a35d-66f2310ce6a9', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 11, 11, 'He gave some to be apostles; and some, prophets; and some, evangelists; and some, shepherds and teachers;'),
  ('a690afcc-9201-5bdd-afdc-7abd5098f428', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 12, 12, 'for the perfecting of the saints, to the work of serving, to the building up of the body of Christ;'),
  ('23e42b53-1849-5ca1-a649-2680d9b47e9f', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 13, 13, 'until we all attain to the unity of the faith, and of the knowledge of the Son of God, to a full grown man, to the measure of the stature of the fullness of Christ;'),
  ('f9e7657d-b531-5c08-a7ae-1cde21eb44e6', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 14, 14, 'that we may no longer be children, tossed back and forth and carried about with every wind of doctrine, by the trickery of men, in craftiness, after the wiles of error;'),
  ('4d6ddbfd-a624-5a1b-ab8f-caaae463ea3e', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 15, 15, 'but speaking truth in love, we may grow up in all things into him, who is the head, Christ;'),
  ('c68c9b5e-bae1-5fd6-a5fa-d6a784028f1b', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 16, 16, 'from whom all the body, being fitted and knit together through that which every joint supplies, according to the working in measure of each individual part, makes the body increase to the building up of itself in love.'),
  ('1bb96052-4af6-5682-a3de-c0e94140c98b', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 17, 17, 'This I say therefore, and testify in the Lord, that you no longer walk as the rest of the Gentiles also walk, in the futility of their mind,'),
  ('4242a229-2dc4-5a1a-ac5d-03dbaea88285', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 18, 18, 'being darkened in their understanding, alienated from the life of God, because of the ignorance that is in them, because of the hardening of their hearts;'),
  ('9eb02797-a902-58fd-a783-13d8cf057242', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 19, 19, 'who having become callous gave themselves up to lust, to work all uncleanness with greediness.'),
  ('25feb82c-4595-58c4-a32a-2bec129ecec3', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 20, 20, 'But you did not learn Christ that way;'),
  ('9225bab8-7280-5cfc-ab83-fa8d974ef52f', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 21, 21, 'if indeed you heard him, and were taught in him, even as truth is in Jesus:'),
  ('b068fac2-292c-5458-a69c-344399a45745', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 22, 22, 'that you put away, as concerning your former way of life, the old man, that grows corrupt after the lusts of deceit;'),
  ('5315f980-7074-50a3-a18c-f6dca6dd2715', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 23, 23, 'and that you be renewed in the spirit of your mind,'),
  ('812f684b-7c7d-50c3-a478-6db1b3f11280', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 24, 24, 'and put on the new man, who in the likeness of God has been created in righteousness and holiness of truth.'),
  ('418d9c87-47f1-5bb8-a151-ff2d1820a7a5', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 25, 25, 'Therefore, putting away falsehood, speak truth each one with his neighbor. For we are members of one another.'),
  ('b2fe8027-e3f1-5f9b-acfc-dd73142dd179', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 26, 26, '"Be angry, and don''t sin." Don''t let the sun go down on your wrath,'),
  ('68b61f66-f918-5dc4-a35c-e82360368077', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 27, 27, 'neither give place to the devil.'),
  ('fc03be29-78bf-54d5-a171-9794c255ebb0', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 28, 28, 'Let him who stole steal no more; but rather let him labor, working with his hands the thing that is good, that he may have something to give to him who has need.'),
  ('9651fdfa-2611-533b-a1b3-be1c0e1dbd4b', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 29, 29, 'Let no corrupt speech proceed out of your mouth, but such as is good for building up as the need may be, that it may give grace to those who hear.'),
  ('a265a79b-6e34-5005-aeb4-178ccb55be7f', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 30, 30, 'Don''t grieve the Holy Spirit of God, in whom you were sealed for the day of redemption.'),
  ('73d3c9ab-101a-5d7e-ae49-06af3e84dbc2', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 31, 31, 'Let all bitterness, wrath, anger, outcry, and slander, be put away from you, with all malice.'),
  ('ec6e2ecf-f6bf-5ccb-a48a-f86a9f6ecc8a', '3d7c1e37-85c4-5af1-a645-b1c6060943e3', NULL, 32, 32, 'And be kind to one another, tenderhearted, forgiving each other, just as God also in Christ forgave you.'),
  ('0520518f-0bcd-5e7c-aa7f-4747561c34ac', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 1, 1, 'Be therefore imitators of God, as beloved children.'),
  ('15926273-6ddf-5c04-ae33-664059f1e84e', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 2, 2, 'Walk in love, even as Christ also loved you, and gave himself up for us, an offering and a sacrifice to God for a sweet-smelling fragrance.'),
  ('173681a6-618f-52d2-a68d-eae2e6197a07', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 3, 3, 'But sexual immorality, and all uncleanness, or covetousness, let it not even be mentioned among you, as becomes saints;'),
  ('522677f4-3d3b-5735-a03e-e04d36baafd1', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 4, 4, 'nor filthiness, nor foolish talking, nor jesting, which are not appropriate; but rather giving of thanks.'),
  ('c9be1d55-d8b9-5270-a40a-f6995478087a', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 5, 5, 'Know this for sure, that no sexually immoral person, nor unclean person, nor covetous man, who is an idolater, has any inheritance in the Kingdom of Christ and God.'),
  ('fb3e7873-60d9-5622-a4cc-b5041ce0cfb1', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 6, 6, 'Let no one deceive you with empty words. For because of these things, the wrath of God comes on the children of disobedience.'),
  ('a745e735-7423-5bc8-a4c5-74922c75e9e4', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 7, 7, 'Therefore don''t be partakers with them.'),
  ('2f2ccf3a-8175-558d-a717-d8d3ac9cbbd4', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 8, 8, 'For you were once darkness, but are now light in the Lord. Walk as children of light,'),
  ('a19db5fc-ffd5-5834-ab01-b5f115184f8b', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 9, 9, 'for the fruit of the Spirit is in all goodness and righteousness and truth,'),
  ('dd51d751-c724-5602-a96a-8ffb4b3073e8', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 10, 10, 'proving what is well pleasing to the Lord.'),
  ('4f59e64d-0580-5684-a7db-72da8d1dcdc7', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 11, 11, 'Have no fellowship with the unfruitful works of darkness, but rather even reprove them.'),
  ('420136a8-1554-5a2b-acde-219e82435642', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 12, 12, 'For the things which are done by them in secret, it is a shame even to speak of.'),
  ('e105f61a-7693-5d36-ae32-8996a6eb40e6', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 13, 13, 'But all things, when they are reproved, are revealed by the light, for everything that reveals is light.'),
  ('acbb7050-9bb9-5ad4-a789-b68a20a13120', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 14, 14, 'Therefore he says, "Awake, you who sleep, and arise from the dead, and Christ will shine on you."'),
  ('51fbcf1d-8b25-5057-add5-34b0810ed022', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 15, 15, 'Therefore watch carefully how you walk, not as unwise, but as wise;'),
  ('1b467cc3-354f-5923-ad94-3947db8c8ddc', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 16, 16, 'redeeming the time, because the days are evil.'),
  ('8c4087c6-0d2a-5648-ab32-d965cbdfef46', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 17, 17, 'Therefore don''t be foolish, but understand what the will of the Lord is.'),
  ('d3b800c8-ffcb-507c-affb-d5cb76a344f2', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 18, 18, 'Don''t be drunken with wine, in which is dissipation, but be filled with the Spirit,'),
  ('1fdc7858-8244-54be-a054-ea29fd068e8c', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 19, 19, 'speaking to one another in psalms, hymns, and spiritual songs; singing, and making melody in your heart to the Lord;'),
  ('fe3ffa1d-b933-5f15-a114-dfb65f485b75', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 20, 20, 'giving thanks always concerning all things in the name of our Lord Jesus Christ, to God, even the Father;'),
  ('527b1192-77ee-538a-a8f2-1724b7d46c68', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 21, 21, 'subjecting yourselves one to another in the fear of Christ.'),
  ('8b7bcb20-1773-5475-a3ab-baa390a02f02', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 22, 22, 'Wives, be subject to your own husbands, as to the Lord.'),
  ('66f62c4f-5396-5bd8-a735-0765255c4476', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 23, 23, 'For the husband is the head of the wife, and Christ also is the head of the assembly, being himself the savior of the body.'),
  ('ee5cb469-d735-5a02-a5da-d1e8ad27497e', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 24, 24, 'But as the assembly is subject to Christ, so let the wives also be to their own husbands in everything.'),
  ('05fe6829-12af-5d9d-a500-ec708cba2665', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 25, 25, 'Husbands, love your wives, even as Christ also loved the assembly, and gave himself up for it;'),
  ('72946f9e-0e26-5718-aee7-d4ef34def495', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 26, 26, 'that he might sanctify it, having cleansed it by the washing of water with the word,'),
  ('0f76aabd-538f-54b7-a3c7-865a70e2e5fb', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 27, 27, 'that he might present the assembly to himself gloriously, not having spot or wrinkle or any such thing; but that it should be holy and without blemish.'),
  ('b4c664f8-4f9e-5235-ac56-b597c6f5f81f', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 28, 28, 'Even so husbands also ought to love their own wives as their own bodies. He who loves his own wife loves himself.'),
  ('88eb343c-7111-5fe8-a3a8-ff3056e198ed', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 29, 29, 'For no man ever hated his own flesh; but nourishes and cherishes it, even as the Lord also does the assembly;'),
  ('6e19c0c8-e587-566f-a1ab-e0684b6d43df', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 30, 30, 'because we are members of his body, of his flesh and bones.'),
  ('8c99851d-a467-5d66-a1c8-d353a54e307c', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 31, 31, '"For this cause a man will leave his father and mother, and will be joined to his wife. The two will become one flesh."'),
  ('78f2fa84-a5ac-56ca-a2d7-6400150561f3', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 32, 32, 'This mystery is great, but I speak concerning Christ and of the assembly.'),
  ('9ab32e3d-44a8-5263-a40a-3142266d14ac', 'fcff1be9-3ae5-5d47-a3aa-04cac925d5ea', NULL, 33, 33, 'Nevertheless each of you must also love his own wife even as himself; and let the wife see that she respects her husband.'),
  ('1cee9c3e-1502-5ee7-af8b-a17295f874fc', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 1, 1, 'Children, obey your parents in the Lord, for this is right.'),
  ('a58535fc-11b2-58be-afce-ca438a3d79d3', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 2, 2, '"Honor your father and mother," which is the first commandment with a promise:'),
  ('898ccc13-0709-5330-a2ec-c0c585a6a228', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 3, 3, '"that it may be well with you, and you may live long on the earth."'),
  ('bf726e74-7f3e-56c3-ae4d-09795edc3ed7', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 4, 4, 'You fathers, don''t provoke your children to wrath, but nurture them in the discipline and instruction of the Lord.'),
  ('f5924cae-69d2-5342-a02b-b006f479c580', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 5, 5, 'Servants, be obedient to those who according to the flesh are your masters, with fear and trembling, in singleness of your heart, as to Christ;'),
  ('6bcc9145-4509-535d-ac85-1a14236823f2', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 6, 6, 'not in the way of service only when eyes are on you, as men pleasers; but as servants of Christ, doing the will of God from the heart;'),
  ('eef92982-74ea-57ea-acd5-c3d974aab5b9', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 7, 7, 'with good will doing service, as to the Lord, and not to men;'),
  ('3e31a45c-dcd5-5c2e-aa3d-c8b2f7cecc6a', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 8, 8, 'knowing that whatever good thing each one does, he will receive the same again from the Lord, whether he is bound or free.'),
  ('43ba34b4-12b7-553d-a3fe-71798b5c6380', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 9, 9, 'You masters, do the same things to them, and give up threatening, knowing that he who is both their Master and yours is in heaven, and there is no partiality with him.'),
  ('eb17d137-bb0e-5fa5-a49d-c3613e3b9338', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 10, 10, 'Finally, be strong in the Lord, and in the strength of his might.'),
  ('cc26da59-2446-5712-a669-2290bea0c0e3', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 11, 11, 'Put on the whole armor of God, that you may be able to stand against the wiles of the devil.'),
  ('a8696e78-521e-5057-aa01-3e5d2c49d431', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 12, 12, 'For our wrestling is not against flesh and blood, but against the principalities, against the powers, against the world''s rulers of the darkness of this age, and against the spiritual forces of wickedness in the heavenly places.'),
  ('c3591a13-f6af-5dd0-a4a6-08a751347bc2', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 13, 13, 'Therefore, put on the whole armor of God, that you may be able to withstand in the evil day, and, having done all, to stand.'),
  ('bb1472c2-2d2b-573e-adb7-45cad5a07458', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 14, 14, 'Stand therefore, having the utility belt of truth buckled around your waist, and having put on the breastplate of righteousness,'),
  ('db9796ba-b3e9-52cb-ae25-9c47f95904bd', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 15, 15, 'and having fitted your feet with the preparation of the Good News of peace;'),
  ('ad60b5ae-969e-50b8-a84b-3001e71201c4', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 16, 16, 'above all, taking up the shield of faith, with which you will be able to quench all the fiery darts of the evil one.'),
  ('aef11fd9-c5d9-53f0-a70a-2ab87c24c12d', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 17, 17, 'And take the helmet of salvation, and the sword of the Spirit, which is the word of God;'),
  ('1f212209-6985-5c63-a36d-e19d467bfe75', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 18, 18, 'with all prayer and requests, praying at all times in the Spirit, and being watchful to this end in all perseverance and requests for all the saints:'),
  ('17b9ac14-fd9e-5f41-a82a-2e32f9c7f2e7', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 19, 19, 'on my behalf, that utterance may be given to me in opening my mouth, to make known with boldness the mystery of the Good News,'),
  ('058ce47c-bf76-519c-add8-f2c50080773d', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 20, 20, 'for which I am an ambassador in chains; that in it I may speak boldly, as I ought to speak.'),
  ('5276ec22-a21f-5615-ab2b-1033522a46bd', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 21, 21, 'But that you also may know my affairs, how I am doing, Tychicus, the beloved brother and faithful servant in the Lord, will make known to you all things;'),
  ('6f4aa1a2-6aa8-5ebe-ad33-a7a38c46a5d8', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 22, 22, 'whom I have sent to you for this very purpose, that you may know our state, and that he may comfort your hearts.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8284332f-06c7-58e1-a955-b73a60c77615', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 23, 23, 'Peace be to the brothers, and love with faith, from God the Father and the Lord Jesus Christ.'),
  ('eb566b80-bd42-5482-ad90-452c8cb13cd5', 'e8c3ef5c-826d-55fa-a743-b0fde6822495', NULL, 24, 24, 'Grace be with all those who love our Lord Jesus Christ with incorruptible love. Amen.'),
  ('c7d46ce2-b2f8-5fee-a8cc-226e9e0cfbb6', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 1, 1, 'Paul and Timothy, servants of Jesus Christ; To all the saints in Christ Jesus who are at Philippi, with the overseers and servants:'),
  ('072223cd-bc04-5a5f-a1c1-98af1dec876c', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 2, 2, 'Grace to you, and peace from God, our Father, and the Lord Jesus Christ.'),
  ('0134fd23-190c-5aa1-acbd-3fbc9ad47940', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 3, 3, 'I thank my God whenever I remember you,'),
  ('fc4470d8-4813-50ad-a18d-a00d4da93231', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 4, 4, 'always in every request of mine on behalf of you all making my requests with joy,'),
  ('5e931814-5cd2-5b85-aeac-16a2101b9d27', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 5, 5, 'for your partnership in furtherance of the Good News from the first day until now;'),
  ('0ab6d419-7b72-57af-a342-728dc8f60862', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 6, 6, 'being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.'),
  ('1214b09a-8bf5-5a38-abb9-61d525c9c03b', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 7, 7, 'It is even right for me to think this way on behalf of all of you, because I have you in my heart, because, both in my bonds and in the defense and confirmation of the Good News, you all are partakers with me of grace.'),
  ('c8dd7d8a-ed3f-5a86-ac6f-0c1634855146', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 8, 8, 'For God is my witness, how I long after all of you in the tender mercies of Christ Jesus.'),
  ('7c9de878-b752-5e7f-aadb-8e4ce5f718ad', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 9, 9, 'This I pray, that your love may abound yet more and more in knowledge and all discernment;'),
  ('4bbc6ee4-f0c4-5da3-ad97-1b05302ec337', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 10, 10, 'so that you may approve the things that are excellent; that you may be sincere and without offense to the day of Christ;'),
  ('7fb2456d-527e-547a-a549-ca6226ba05e9', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 11, 11, 'being filled with the fruits of righteousness, which are through Jesus Christ, to the glory and praise of God.'),
  ('01972c9b-e8a0-54d0-a18d-43a6a4abae64', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 12, 12, 'Now I desire to have you know, brothers, that the things which happened to me have turned out rather to the progress of the Good News;'),
  ('6dd1d2e7-c69d-5736-ade6-e2d6f1ef366e', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 13, 13, 'so that it became evident to the whole palace guard, and to all the rest, that my bonds are in Christ;'),
  ('68370ec7-fc4b-53bc-a3c8-e3bff1357b90', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 14, 14, 'and that most of the brothers in the Lord, being confident through my bonds, are more abundantly bold to speak the word of God without fear.'),
  ('54a282db-629a-5546-a6e0-cb0e8f172cac', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 15, 15, 'Some indeed preach Christ even out of envy and strife, and some also out of good will.'),
  ('0e6017a9-e9f8-5fdc-a75f-8e09ad5bd546', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 16, 16, 'The former insincerely preach Christ from selfish ambition, thinking that they add affliction to my chains;'),
  ('abe9691f-58f8-5154-a18f-9739ebf47002', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 17, 17, 'but the latter out of love, knowing that I am appointed for the defense of the Good News.'),
  ('10a7a79c-6aa3-5916-ab30-4c1ef5b4cba4', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 18, 18, 'What does it matter? Only that in every way, whether in pretense or in truth, Christ is proclaimed. I rejoice in this, yes, and will rejoice.'),
  ('7311eade-f558-5231-a836-f98d8a67ba89', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 19, 19, 'For I know that this will turn out to my salvation, through your supplication and the supply of the Spirit of Jesus Christ,'),
  ('a605d7ea-8184-5238-a172-af9b31e94521', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 20, 20, 'according to my earnest expectation and hope, that I will in no way be disappointed, but with all boldness, as always, now also Christ will be magnified in my body, whether by life, or by death.'),
  ('7b0455fd-b8d3-5904-a391-0467bfb80431', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 21, 21, 'For to me to live is Christ, and to die is gain.'),
  ('cfc64e8f-7f33-55d9-ad64-72a5f169a652', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 22, 22, 'But if I live on in the flesh, this will bring fruit from my work; yet I don''t know what I will choose.'),
  ('077e26cf-aca6-55c0-ab03-244512a232d8', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 23, 23, 'But I am in a dilemma between the two, having the desire to depart and be with Christ, which is far better.'),
  ('35d3b220-8251-5acb-aa55-8d88fc7193b2', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 24, 24, 'Yet, to remain in the flesh is more needful for your sake.'),
  ('cd98e75b-5dda-5bd9-aa26-b7c1f8ce407d', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 25, 25, 'Having this confidence, I know that I will remain, yes, and remain with you all, for your progress and joy in the faith,'),
  ('50d653a7-ee5d-5949-ab24-1e048423890c', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 26, 26, 'that your rejoicing may abound in Christ Jesus in me through my presence with you again.'),
  ('e84d5ee2-b596-5d07-a30c-b7d43fe75435', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 27, 27, 'Only let your way of life be worthy of the Good News of Christ, that, whether I come and see you or am absent, I may hear of your state, that you stand firm in one spirit, with one soul striving for the faith of the Good News;'),
  ('14f024b7-e411-5d9e-a81c-26bd6dc85379', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 28, 28, 'and in nothing frightened by the adversaries, which is for them a proof of destruction, but to you of salvation, and that from God.'),
  ('8d4ce575-c669-5a2a-a89b-d95c75eb2198', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 29, 29, 'Because it has been granted to you on behalf of Christ, not only to believe in him, but also to suffer on his behalf,'),
  ('5323c762-dc6e-54e8-ab03-c9186d2a33b1', 'a595fc2b-2823-5272-af12-345ad66f3a05', NULL, 30, 30, 'having the same conflict which you saw in me, and now hear is in me.'),
  ('137ecbc4-0848-576e-a064-697a7fdec75d', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 1, 1, 'If there is therefore any exhortation in Christ, if any consolation of love, if any fellowship of the Spirit, if any tender mercies and compassion,'),
  ('b1c8dfe0-857b-5895-a93d-91ce991a44b1', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 2, 2, 'make my joy full, by being like-minded, having the same love, being of one accord, of one mind;'),
  ('1c1e0ea5-a143-5949-a9fa-b6ca6ab9ee2b', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 3, 3, 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself;'),
  ('ff262810-5d8c-5795-a25e-2999e30d0aff', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 4, 4, 'each of you not just looking to his own things, but each of you also to the things of others.'),
  ('5c12d766-c10e-5704-a9e8-fc4a526ad270', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 5, 5, 'Have this in your mind, which was also in Christ Jesus,'),
  ('3f478db2-0c86-5f00-a007-b71e4eaac63e', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 6, 6, 'who, existing in the form of God, didn''t consider equality with God a thing to be grasped,'),
  ('c975e15f-03ce-591a-a889-a444e98f817f', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 7, 7, 'but emptied himself, taking the form of a servant, being made in the likeness of men.'),
  ('b344c5d0-26ee-5315-a635-1629738ca7f3', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 8, 8, 'And being found in human form, he humbled himself, becoming obedient to death, yes, the death of the cross.'),
  ('2e0523ab-c9a6-57bc-a4e0-6d9273cf4c94', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 9, 9, 'Therefore God also highly exalted him, and gave to him the name which is above every name;'),
  ('e8865b17-cf36-5fd6-a2ef-15845d45edca', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 10, 10, 'that at the name of Jesus every knee should bow, of those in heaven, those on earth, and those under the earth,'),
  ('0477d702-925a-5b65-a21e-efe9dbf26d6a', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 11, 11, 'and that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.'),
  ('c9c5dbd0-43df-5a86-a407-9bec479101aa', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 12, 12, 'So then, my beloved, even as you have always obeyed, not only in my presence, but now much more in my absence, work out your own salvation with fear and trembling.'),
  ('ca8ef099-7393-57fe-a93e-5dc65625adc1', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 13, 13, 'For it is God who works in you both to will and to work, for his good pleasure.'),
  ('eca7b3bb-51a9-57d5-a648-889d74865624', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 14, 14, 'Do all things without murmurings and disputes,'),
  ('e9925c04-3b14-5092-ad53-2980aa9c780e', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 15, 15, 'that you may become blameless and harmless, children of God without blemish in the midst of a crooked and perverse generation, among whom you are seen as lights in the world,'),
  ('928e78b1-3f5a-585a-a49c-7d4c6d107a14', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 16, 16, 'holding up the word of life; that I may have something to boast in the day of Christ, that I didn''t run in vain nor labor in vain.'),
  ('dfa65c5c-8162-5dc7-a59c-b6601bc5edc3', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 17, 17, 'Yes, and if I am poured out on the sacrifice and service of your faith, I rejoice, and rejoice with you all.'),
  ('a70edacb-a7d2-579d-a2d5-3b7300315b4e', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 18, 18, 'In the same way, you also rejoice, and rejoice with me.'),
  ('8f7c96f7-8c9f-50c2-abee-4e40fb7d06dd', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 19, 19, 'But I hope in the Lord Jesus to send Timothy to you soon, that I also may be cheered up when I know how you are doing.'),
  ('46bddf44-4af5-5f2e-aadb-8922af296312', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 20, 20, 'For I have no one else like-minded, who will truly care about you.'),
  ('410cb0d7-3f21-5203-a46a-35c530c693a7', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 21, 21, 'For they all seek their own, not the things of Jesus Christ.'),
  ('af17e139-3fbb-5b99-a86d-1d530677a754', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 22, 22, 'But you know the proof of him, that, as a child serves a father, so he served with me in furtherance of the Good News.'),
  ('ae8ae9af-e5d1-52a9-a5de-6afbe9305f6f', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 23, 23, 'Therefore I hope to send him at once, as soon as I see how it will go with me.'),
  ('bd041ec7-42b6-5afe-a273-86f50d80c708', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 24, 24, 'But I trust in the Lord that I myself also will come shortly.'),
  ('95f65443-e1f1-5ec7-a247-10c18cdd886c', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 25, 25, 'But I counted it necessary to send to you Epaphroditus, my brother, fellow worker, fellow soldier, and your apostle and servant of my need;'),
  ('17f0cf05-ec99-511c-aa12-b4d891e2ebd6', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 26, 26, 'since he longed for you all, and was very troubled, because you had heard that he was sick.'),
  ('149d90b7-49a5-5020-a1b4-29673156defa', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 27, 27, 'For indeed he was sick, nearly to death, but God had mercy on him; and not on him only, but on me also, that I might not have sorrow on sorrow.'),
  ('12516de0-f6ad-5e70-ac6b-2e6679fb63d9', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 28, 28, 'I have sent him therefore the more diligently, that, when you see him again, you may rejoice, and that I may be the less sorrowful.'),
  ('3721060d-e30c-517f-a1b0-97b2f2037a9a', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 29, 29, 'Receive him therefore in the Lord with all joy, and hold such in honor,'),
  ('2488e383-d287-5f65-a88d-c6c5cae05478', '832c05a7-66b4-527a-ae0a-d3b0fc8c6638', NULL, 30, 30, 'because for the work of Christ he came near to death, risking his life to supply that which was lacking in your service toward me.'),
  ('b23b9d73-6c36-51c8-a3cd-1164dd110b88', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 1, 1, 'Finally, my brothers, rejoice in the Lord. To write the same things to you, to me indeed is not tiresome, but for you it is safe.'),
  ('bb411b3c-08d2-58cf-a4b3-16b0b38ab998', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 2, 2, 'Beware of the dogs, beware of the evil workers, beware of the false circumcision.'),
  ('609d5da0-d1a4-5e9a-ae35-6b29f8ccb876', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 3, 3, 'For we are the circumcision, who worship God in the Spirit, and rejoice in Christ Jesus, and have no confidence in the flesh;'),
  ('c93b77fa-135f-550d-adaa-f8255426b542', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 4, 4, 'though I myself might have confidence even in the flesh. If any other man thinks that he has confidence in the flesh, I yet more:'),
  ('a54fbe08-becd-527a-a6ea-5958993728e3', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 5, 5, 'circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, a Hebrew of Hebrews; concerning the law, a Pharisee;'),
  ('0564ba78-d837-5bfa-ade6-d2b59cfaa284', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 6, 6, 'concerning zeal, persecuting the assembly; concerning the righteousness which is in the law, found blameless.'),
  ('83c99a08-a892-5eb4-aad8-e3b036b4d8fb', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 7, 7, 'However, what things were gain to me, these have I counted loss for Christ.'),
  ('b0348526-ca7f-589b-ad81-804321a21464', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 8, 8, 'Yes most certainly, and I count all things to be loss for the excellency of the knowledge of Christ Jesus, my Lord, for whom I suffered the loss of all things, and count them nothing but refuse, that I may gain Christ'),
  ('d087d579-3f7d-53d6-a8c3-dfe404b3658b', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 9, 9, 'and be found in him, not having a righteousness of my own, that which is of the law, but that which is through faith in Christ, the righteousness which is from God by faith;'),
  ('e0f27641-52b0-58cf-a829-90e1a53a23b2', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 10, 10, 'that I may know him, and the power of his resurrection, and the fellowship of his sufferings, becoming conformed to his death;'),
  ('7ddee147-6b7e-5c97-ac7f-23382821dbaa', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 11, 11, 'if by any means I may attain to the resurrection from the dead.'),
  ('b0e395cb-ee4c-5d72-a6a2-6b4ccb9fa725', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 12, 12, 'Not that I have already obtained, or am already made perfect; but I press on, if it is so that I may take hold of that for which also I was taken hold of by Christ Jesus.'),
  ('acf90b9c-5953-58f9-a6f3-661654c86e4a', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 13, 13, 'Brothers, I don''t regard myself as yet having taken hold, but one thing I do. Forgetting the things which are behind, and stretching forward to the things which are before,'),
  ('7174e160-6884-5fda-a527-159074c74912', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 14, 14, 'I press on toward the goal for the prize of the high calling of God in Christ Jesus.'),
  ('c418f006-ff93-5252-a1c2-facb0e98667d', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 15, 15, 'Let us therefore, as many as are perfect, think this way. If in anything you think otherwise, God will also reveal that to you.'),
  ('b2d8f594-c882-54e1-a595-5e956d5f9704', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 16, 16, 'Nevertheless, to the extent that we have already attained, let us walk by the same rule. Let us be of the same mind.'),
  ('775973d3-5e97-5e36-a233-9d45b8a40421', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 17, 17, 'Brothers, be imitators together of me, and note those who walk this way, even as you have us for an example.'),
  ('0fc20800-8e0c-5c1d-a4f1-9672e54a8e18', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 18, 18, 'For many walk, of whom I told you often, and now tell you even weeping, as the enemies of the cross of Christ,'),
  ('b07fc9b4-627f-55dd-a611-48ab4a2b17a5', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 19, 19, 'whose end is destruction, whose god is the belly, and whose glory is in their shame, who think about earthly things.'),
  ('b9d98366-cfad-5bcf-a6a8-60b48de1c590', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 20, 20, 'For our citizenship is in heaven, from where we also wait for a Savior, the Lord Jesus Christ;'),
  ('bcd290cb-a023-5c39-a7f6-81e856c5bbbc', '13f87502-453c-599b-a68d-95a09c9ddfff', NULL, 21, 21, 'who will change the body of our humiliation to be conformed to the body of his glory, according to the working by which he is able even to subject all things to himself.'),
  ('26003cae-4033-5d5d-a62d-aa1088c016f1', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 1, 1, 'Therefore, my brothers, beloved and longed for, my joy and crown, so stand firm in the Lord, my beloved.'),
  ('66ac29fc-2a63-5a15-a6c9-1137fa60cd7c', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 2, 2, 'I exhort Euodia, and I exhort Syntyche, to think the same way in the Lord.'),
  ('91396afb-1aef-56e2-a4ec-3fc85aee51da', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 3, 3, 'Yes, I beg you also, true yokefellow, help these women, for they labored with me in the Good News, with Clement also, and the rest of my fellow workers, whose names are in the book of life.'),
  ('adbe31fa-0b15-58d2-ae56-7e341ae98815', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 4, 4, 'Rejoice in the Lord always! Again I will say, Rejoice!'),
  ('56d57ef1-788a-58df-a94b-cc8f573874f3', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 5, 5, 'Let your gentleness be known to all men. The Lord is at hand.'),
  ('30836202-ed63-53e4-a87f-08ca075d7e02', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 6, 6, 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.'),
  ('1703fdbc-a3a1-5bc5-afcc-900609279c0a', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 7, 7, 'And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.'),
  ('b56484e0-887e-52dc-ae82-f1432e95085c', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 8, 8, 'Finally, brothers, whatever things are true, whatever things are honorable, whatever things are just, whatever things are pure, whatever things are lovely, whatever things are of good report; if there is any virtue, and if there is any praise, think about these things.'),
  ('d9e9d848-2a96-53b4-a4c2-d52ac7ac9499', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 9, 9, 'The things which you learned, received, heard, and saw in me: do these things, and the God of peace will be with you.'),
  ('c29e3685-2052-52f4-a33f-a8560b5d4ec9', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 10, 10, 'But I rejoice in the Lord greatly, that now at length you have revived your thought for me; in which you did indeed take thought, but you lacked opportunity.'),
  ('4a376279-d33d-5240-ad12-c55be54a595e', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 11, 11, 'Not that I speak in respect to lack, for I have learned in whatever state I am, to be content in it.'),
  ('21bfbe7f-5908-520e-ac13-09f1b6867fbd', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 12, 12, 'I know how to be humbled, and I know also how to abound. In everything and in all things I have learned the secret both to be filled and to be hungry, both to abound and to be in need.'),
  ('9c855624-6784-5393-a9f1-1fa686cbd7b5', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 13, 13, 'I can do all things through Christ, who strengthens me.'),
  ('0f05c9fe-c9e3-5d86-a0f7-f68b07cb807b', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 14, 14, 'However you did well that you shared in my affliction.'),
  ('956ac2d7-23c4-5e71-a421-a4494a7a92c8', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 15, 15, 'You yourselves also know, you Philippians, that in the beginning of the Good News, when I departed from Macedonia, no assembly shared with me in the matter of giving and receiving but you only.'),
  ('f1b1d7e9-daf3-57fc-a4e9-282283c041c5', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 16, 16, 'For even in Thessalonica you sent once and again to my need.'),
  ('193f96ee-e16e-5e82-ac97-051073109813', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 17, 17, 'Not that I seek for the gift, but I seek for the fruit that increases to your account.'),
  ('245106a7-4b74-562f-aead-3ae611eb01b8', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 18, 18, 'But I have all things, and abound. I am filled, having received from Epaphroditus the things that came from you, a sweet-smelling fragrance, an acceptable and well-pleasing sacrifice to God.'),
  ('f0f36c0b-da29-56ac-a9b9-027ab71a8572', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 19, 19, 'My God will supply every need of yours according to his riches in glory in Christ Jesus.'),
  ('798e1afc-56cb-5e1a-a476-639b4ae3c58c', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 20, 20, 'Now to our God and Father be the glory forever and ever! Amen.'),
  ('fbf63cbc-941b-51b3-a7c7-548e0f2f93d5', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 21, 21, 'Greet every saint in Christ Jesus. The brothers who are with me greet you.'),
  ('d52e0869-99a4-5fb5-aa16-95453df0faa0', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 22, 22, 'All the saints greet you, especially those who are of Caesar''s household.'),
  ('2ad9a680-bec4-5cd8-a88c-1e9570c6d23a', '9aa8d18d-9aa1-5531-ae0b-3d1f533c3966', NULL, 23, 23, 'The grace of the Lord Jesus Christ be with you all. Amen.'),
  ('c0b3902a-7957-59a5-a5f0-8a73999c1a86', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 1, 1, 'Paul, an apostle of Christ Jesus through the will of God, and Timothy our brother,'),
  ('3adf95d7-9a12-5e7a-a4fc-480c074c6b89', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 2, 2, 'to the saints and faithful brothers in Christ at Colossae: Grace to you and peace from God our Father, and the Lord Jesus Christ.'),
  ('f6bd6e88-8984-5707-aa83-7c988bf644f9', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 3, 3, 'We give thanks to God the Father of our Lord Jesus Christ, praying always for you,'),
  ('3cba4066-19d4-59a9-ac64-25a39650b0c2', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 4, 4, 'having heard of your faith in Christ Jesus, and of the love which you have toward all the saints,'),
  ('d42cc99e-5451-535b-a80b-be1a0e90c8f7', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 5, 5, 'because of the hope which is laid up for you in the heavens, of which you heard before in the word of the truth of the Good News,'),
  ('89b1fe9f-68c2-5b7a-ad2c-98dca6d837cc', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 6, 6, 'which has come to you; even as it is in all the world and is bearing fruit and growing, as it does in you also, since the day you heard and knew the grace of God in truth;'),
  ('bb4003e8-8dff-5db8-a566-dacfbcd3b933', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 7, 7, 'even as you learned of Epaphras our beloved fellow servant, who is a faithful servant of Christ on our behalf,'),
  ('5bbddb82-ae98-575e-a64b-b3a2b7e87cf2', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 8, 8, 'who also declared to us your love in the Spirit.'),
  ('17d1fde1-f488-5187-aa83-c9082792a1a7', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 9, 9, 'For this cause, we also, since the day we heard this, don''t cease praying and making requests for you, that you may be filled with the knowledge of his will in all spiritual wisdom and understanding,'),
  ('361f4d89-3f83-5d7a-a695-1b92bb7027e8', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 10, 10, 'that you may walk worthily of the Lord, to please him in all respects, bearing fruit in every good work, and increasing in the knowledge of God;'),
  ('82782828-6c45-5d66-a241-ba188a1ee8be', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 11, 11, 'strengthened with all power, according to the might of his glory, for all endurance and perseverance with joy;'),
  ('04920b12-e844-5d0f-af0b-43e11861ce73', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 12, 12, 'giving thanks to the Father, who made us fit to be partakers of the inheritance of the saints in light;'),
  ('582f5450-16a3-581a-aa70-eacc5a12025f', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 13, 13, 'who delivered us out of the power of darkness, and translated us into the Kingdom of the Son of his love;'),
  ('abec58e5-99f2-5192-a1b3-327710a2ce8b', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 14, 14, 'in whom we have our redemption, the forgiveness of our sins;'),
  ('1244f22e-7635-5834-a731-8a8a3686a0d1', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 15, 15, 'who is the image of the invisible God, the firstborn of all creation.'),
  ('e3832037-1ea3-5e82-a807-a98735a24842', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 16, 16, 'For by him all things were created, in the heavens and on the earth, things visible and things invisible, whether thrones or dominions or principalities or powers; all things have been created through him, and for him.'),
  ('960c9a05-9925-5649-ab48-9beff9c1eff1', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 17, 17, 'He is before all things, and in him all things are held together.'),
  ('27961744-35bf-5392-a3ae-5c0992d92011', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 18, 18, 'He is the head of the body, the assembly, who is the beginning, the firstborn from the dead; that in all things he might have the preeminence.'),
  ('b26289e2-d21b-5dd7-a059-c31f16404275', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 19, 19, 'For all the fullness was pleased to dwell in him;'),
  ('35d61241-e784-5990-a1e7-b6a1c89fdbeb', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 20, 20, 'and through him to reconcile all things to himself, by him, whether things on the earth, or things in the heavens, having made peace through the blood of his cross.'),
  ('a7c45d81-7962-5f7f-a9ad-ce686be84e1d', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 21, 21, 'You, being in past times alienated and enemies in your mind in your evil works,'),
  ('155d0b50-43da-5171-ae2a-cc7eea937f74', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 22, 22, 'yet now he has reconciled in the body of his flesh through death, to present you holy and without blemish and blameless before him,'),
  ('9c5071e9-3870-5b89-a732-aeea014f55c1', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 23, 23, 'if it is so that you continue in the faith, grounded and steadfast, and not moved away from the hope of the Good News which you heard, which is being proclaimed in all creation under heaven; of which I, Paul, was made a servant.'),
  ('82729fbe-afe5-5602-a40a-3e61d10c4abd', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 24, 24, 'Now I rejoice in my sufferings for your sake, and fill up on my part that which is lacking of the afflictions of Christ in my flesh for his body''s sake, which is the assembly;'),
  ('6a293aa0-a614-5ed5-adc0-3d6bd695b952', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 25, 25, 'of which I was made a servant, according to the stewardship of God which was given me toward you, to fulfill the word of God,'),
  ('93833290-1d35-500f-af35-19771b1a88c0', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 26, 26, 'the mystery which has been hidden for ages and generations. But now it has been revealed to his saints,'),
  ('b538ccd2-e894-53d6-ab81-ad572c5de6c5', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 27, 27, 'to whom God was pleased to make known what are the riches of the glory of this mystery among the Gentiles, which is Christ in you, the hope of glory;'),
  ('86ecaed5-9c34-5f55-aa7d-e629925f2e76', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 28, 28, 'whom we proclaim, admonishing every man and teaching every man in all wisdom, that we may present every man perfect in Christ Jesus;'),
  ('e49d0699-f590-595a-ac7c-676341c51810', 'e1c79d44-4ba5-5f90-a989-9ff3400ef712', NULL, 29, 29, 'for which I also labor, striving according to his working, which works in me mightily.'),
  ('d638ed91-76dc-5a12-af07-f5799af25d90', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 1, 1, 'For I desire to have you know how greatly I struggle for you, and for those at Laodicea, and for as many as have not seen my face in the flesh;'),
  ('9c663602-b1c0-5506-a39a-b803a7d8adba', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 2, 2, 'that their hearts may be comforted, they being knit together in love, and gaining all riches of the full assurance of understanding, that they may know the mystery of God, both of the Father and of Christ,'),
  ('1e0788cd-0743-5775-ac20-f3d7d0ed3a5c', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 3, 3, 'in whom are all the treasures of wisdom and knowledge hidden.'),
  ('8b979360-4ebe-546d-a36a-23e3355a9645', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 4, 4, 'Now this I say that no one may delude you with persuasiveness of speech.'),
  ('27066b96-1e2c-58dc-aefe-fc91a74682ef', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 5, 5, 'For though I am absent in the flesh, yet am I with you in the spirit, rejoicing and seeing your order, and the steadfastness of your faith in Christ.'),
  ('4fff4991-fe27-56de-aa29-ef0a12116ebe', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 6, 6, 'As therefore you received Christ Jesus, the Lord, walk in him,'),
  ('073fff1e-3393-5264-a2f4-25227885e2be', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 7, 7, 'rooted and built up in him, and established in the faith, even as you were taught, abounding in it in thanksgiving.'),
  ('f5e746d7-a1c8-5093-a130-5c4ab7f57c6d', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 8, 8, 'Be careful that you don''t let anyone rob you through his philosophy and vain deceit, after the tradition of men, after the elements of the world, and not after Christ.'),
  ('12b80a98-e12f-5ff5-ae78-10df118e7606', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 9, 9, 'For in him all the fullness of the Godhead dwells bodily,'),
  ('e188adf3-fb06-505b-a8c1-b3e2d292b01b', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 10, 10, 'and in him you are made full, who is the head of all principality and power;'),
  ('641bb10c-014f-5d63-a457-cadffca640f0', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 11, 11, 'in whom you were also circumcised with a circumcision not made with hands, in the putting off of the body of the sins of the flesh, in the circumcision of Christ;'),
  ('e35ca8cd-42b4-5e3e-a9ed-5e6364c37ddd', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 12, 12, 'having been buried with him in baptism, in which you were also raised with him through faith in the working of God, who raised him from the dead.'),
  ('3af34c07-0715-5774-aaea-bf562ec80c60', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 13, 13, 'You were dead through your trespasses and the uncircumcision of your flesh. He made you alive together with him, having forgiven us all our trespasses,'),
  ('81ceb359-35f0-5fc9-aa22-c047ba193e1c', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 14, 14, 'wiping out the handwriting in ordinances which was against us; and he has taken it out of the way, nailing it to the cross;'),
  ('e12656db-77bc-5350-ab12-3bcd34641be1', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 15, 15, 'having stripped the principalities and the powers, he made a show of them openly, triumphing over them in it.'),
  ('b2c2fe97-785e-5c6d-a608-ab67e1a86055', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 16, 16, 'Let no one therefore judge you in eating, or in drinking, or with respect to a feast day or a new moon or a Sabbath day,'),
  ('f6ed8a22-5d2d-5f97-a63d-e680fddfcea0', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 17, 17, 'which are a shadow of the things to come; but the body is Christ''s.'),
  ('92eb04ab-e9e9-5b07-ab85-2dd31348183f', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 18, 18, 'Let no one rob you of your prize by a voluntary humility and worshipping of the angels, dwelling in the things which he has not seen, vainly puffed up by his fleshly mind,'),
  ('8076095b-5260-5832-a059-f26399a6a4b2', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 19, 19, 'and not holding firmly to the Head, from whom all the body, being supplied and knit together through the joints and ligaments, grows with God''s growth.'),
  ('78c9be52-d51f-5916-aa19-c84e8300f88e', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 20, 20, 'If you died with Christ from the elements of the world, why, as though living in the world, do you subject yourselves to ordinances,'),
  ('e2f28b14-6336-5a6f-a87b-03126f47d8b9', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 21, 21, '"Don''t handle, nor taste, nor touch"'),
  ('1e287fcb-2aa4-5eeb-a8e4-a9330bce567e', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 22, 22, '(all of which perish with use), according to the precepts and doctrines of men?'),
  ('c41ef657-67bb-55ec-a439-59a2f849e81b', '0e542757-385a-5035-a4ee-1461b5e62fdc', NULL, 23, 23, 'Which things indeed appear like wisdom in self-imposed worship, and humility, and severity to the body; but aren''t of any value against the indulgence of the flesh.'),
  ('f0906e65-42a6-55a5-a740-fd6bc8cb13f8', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 1, 1, 'If then you were raised together with Christ, seek the things that are above, where Christ is, seated on the right hand of God.'),
  ('b7ebef4f-f6ab-5518-a519-f1f9d96e14df', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 2, 2, 'Set your mind on the things that are above, not on the things that are on the earth.'),
  ('bbcac574-ac87-564a-a07f-6a621e93c07e', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 3, 3, 'For you died, and your life is hidden with Christ in God.'),
  ('814c0b4f-2e92-5992-a344-72be516abe54', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 4, 4, 'When Christ, our life, is revealed, then you will also be revealed with him in glory.'),
  ('e4988a96-efa1-53e6-abd6-55127af724d6', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 5, 5, 'Put to death therefore your members which are on the earth: sexual immorality, uncleanness, depraved passion, evil desire, and covetousness, which is idolatry;'),
  ('ba924a94-bbdd-5647-a4a4-a5b5828a93f1', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 6, 6, 'for which things'' sake the wrath of God comes on the children of disobedience.'),
  ('0d8ad8fa-3b84-50a3-ac82-70e52500bc2b', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 7, 7, 'You also once walked in those, when you lived in them;'),
  ('acdbdf3d-3515-55c6-a1fe-a1b5ba78f27d', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 8, 8, 'but now you also put them all away: anger, wrath, malice, slander, and shameful speaking out of your mouth.'),
  ('64d0e479-0c3a-5f38-a2d6-fc81f5af5dcc', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 9, 9, 'Don''t lie to one another, seeing that you have put off the old man with his doings,'),
  ('d5261b14-006b-5a57-a6bc-e2660f4b2643', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 10, 10, 'and have put on the new man, who is being renewed in knowledge after the image of his Creator,'),
  ('7ad1a3be-de44-5590-a5e3-2c910aa06fc5', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 11, 11, 'where there can''t be Greek and Jew, circumcision and uncircumcision, barbarian, Scythian, bondservant, freeman; but Christ is all, and in all.'),
  ('e4793393-e5cf-5c27-a2f2-2fe61dc8a45b', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 12, 12, 'Put on therefore, as God''s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance;'),
  ('61afe056-d4d3-5f76-abf2-ec5537b626bf', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 13, 13, 'bearing with one another, and forgiving each other, if any man has a complaint against any; even as Christ forgave you, so you also do.'),
  ('81924650-5825-510f-a97b-6c2ec92d2024', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 14, 14, 'Above all these things, walk in love, which is the bond of perfection.'),
  ('3210164c-84d5-5f97-ad63-aa14acd56a7f', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 15, 15, 'And let the peace of God rule in your hearts, to which also you were called in one body; and be thankful.'),
  ('edfa2f45-830f-500f-ad2b-4c4c08cfcac6', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 16, 16, 'Let the word of Christ dwell in you richly; in all wisdom teaching and admonishing one another with psalms, hymns, and spiritual songs, singing with grace in your heart to the Lord.'),
  ('c6f6ad79-0dec-5576-aa6f-7972737facc8', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 17, 17, 'Whatever you do, in word or in deed, do all in the name of the Lord Jesus, giving thanks to God the Father, through him.'),
  ('d9fcdc00-ecb6-55ff-a9e3-bc26fba6a0f8', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 18, 18, 'Wives, be in subjection to your husbands, as is fitting in the Lord.'),
  ('3056991e-1544-5d9a-ad64-d1bef5965a66', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 19, 19, 'Husbands, love your wives, and don''t be bitter against them.'),
  ('8c62ac04-149c-509f-a4fd-a24a97eeb020', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 20, 20, 'Children, obey your parents in all things, for this pleases the Lord.'),
  ('49fc19d5-84cd-5c02-a711-9f4c93c562f2', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 21, 21, 'Fathers, don''t provoke your children, so that they won''t be discouraged.'),
  ('8e18180c-ff10-54f0-ae62-62a966e6e93a', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 22, 22, 'Servants, obey in all things those who are your masters according to the flesh, not just when they are looking, as men pleasers, but in singleness of heart, fearing God.'),
  ('57ba85ca-4b08-5947-a3b2-0a39e7002be9', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 23, 23, 'And whatever you do, work heartily, as for the Lord, and not for men,'),
  ('2908900b-d215-56fb-a089-109ce8db6594', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 24, 24, 'knowing that from the Lord you will receive the reward of the inheritance; for you serve the Lord Christ.'),
  ('9e567877-09b5-5e3b-a2bf-b79c13b97721', '93953ed6-f245-5377-a78c-7e95904bcad2', NULL, 25, 25, 'But he who does wrong will receive again for the wrong that he has done, and there is no partiality.'),
  ('804860f9-fec0-5bdf-aa08-ac9e1ed813cc', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 1, 1, 'Masters, give to your servants that which is just and equal, knowing that you also have a Master in heaven.'),
  ('63453d0a-a232-5a22-afc2-6bb967c6a650', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 2, 2, 'Continue steadfastly in prayer, watching therein with thanksgiving;'),
  ('c7f5987e-90f1-5f7a-afd6-8202fab8c2cc', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 3, 3, 'praying together for us also, that God may open to us a door for the word, to speak the mystery of Christ, for which I am also in bonds;'),
  ('4d91233b-764a-53a8-a329-12f724e9ebfe', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 4, 4, 'that I may reveal it as I ought to speak.'),
  ('465e8854-f816-5378-ac19-199de52f7f20', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 5, 5, 'Walk in wisdom toward those who are outside, redeeming the time.'),
  ('22c3c5db-949b-512c-a7cc-a2563e3a4d16', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 6, 6, 'Let your speech always be with grace, seasoned with salt, that you may know how you ought to answer each one.'),
  ('d7c19a90-1c02-5951-a51a-89fe55e589bf', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 7, 7, 'All my affairs will be made known to you by Tychicus, the beloved brother, faithful servant, and fellow bondservant in the Lord.'),
  ('c5b318be-5557-505f-a9e4-aa2c89fe9705', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 8, 8, 'I am sending him to you for this very purpose, that he may know your circumstances and comfort your hearts,'),
  ('c97afe58-d486-57c6-ab0f-bb58b65e10c1', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 9, 9, 'together with Onesimus, the faithful and beloved brother, who is one of you. They will make known to you everything that is going on here.'),
  ('b2096113-8f79-576e-ada5-5a1cfd4d3bce', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 10, 10, 'Aristarchus, my fellow prisoner, greets you, and Mark, the cousin of Barnabas (concerning whom you received commandments, "if he comes to you, receive him"),'),
  ('3a048b52-4533-5331-a89f-0e02de807ee6', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 11, 11, 'and Jesus who is called Justus. These are my only fellow workers for the Kingdom of God who are of the circumcision, men who have been a comfort to me.'),
  ('58a7e7f7-7981-5ab6-ac95-caf285325edc', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 12, 12, 'Epaphras, who is one of you, a servant of Christ, salutes you, always striving for you in his prayers, that you may stand perfect and complete in all the will of God.'),
  ('6f27d2ac-f691-576a-aa62-d219f484edce', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 13, 13, 'For I testify about him, that he has great zeal for you, and for those in Laodicea, and for those in Hierapolis.'),
  ('3e73b09e-4820-502a-a4e8-b3e484038fe9', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 14, 14, 'Luke, the beloved physician, and Demas greet you.'),
  ('337c212b-b97b-5e67-a7cd-ef73d9a4d04b', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 15, 15, 'Greet the brothers who are in Laodicea, and Nymphas, and the assembly that is in his house.'),
  ('b994a092-f696-5e5e-a83d-465553d04714', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 16, 16, 'When this letter has been read among you, cause it to be read also in the assembly of the Laodiceans; and that you also read the letter from Laodicea.'),
  ('477f268a-bcf0-577d-a462-6ed786cd7d6a', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 17, 17, 'Tell Archippus, "Take heed to the ministry which you have received in the Lord, that you fulfill it."'),
  ('27903afe-67c3-521d-a532-f0133fa0cac9', 'c3d4c790-7c8d-54ad-a786-bed6a9a66bda', NULL, 18, 18, 'The salutation of me, Paul, with my own hand: remember my bonds. Grace be with you. Amen.'),
  ('c4a9d27d-4e94-581f-a811-4f9a5d2c1766', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 1, 1, 'Paul, Silvanus, and Timothy, to the assembly of the Thessalonians in God the Father and the Lord Jesus Christ: Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('3c19d078-e455-54e4-a3fe-df1f63f4eb15', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 2, 2, 'We always give thanks to God for all of you, mentioning you in our prayers,'),
  ('bbf8091b-39ba-59cc-ae0a-758b2ec29173', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 3, 3, 'remembering without ceasing your work of faith and labor of love and patience of hope in our Lord Jesus Christ, before our God and Father.'),
  ('0ff514aa-26ca-5c17-a874-b597644b7673', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 4, 4, 'We know, brothers loved by God, that you are chosen,'),
  ('756b8618-26e8-5879-ad65-1e3553500630', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 5, 5, 'and that our Good News came to you not in word only, but also in power, and in the Holy Spirit, and with much assurance. You know what kind of men we showed ourselves to be among you for your sake.'),
  ('ffed2109-1361-53a5-a5f3-c168d2c6730e', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 6, 6, 'You became imitators of us, and of the Lord, having received the word in much affliction, with joy of the Holy Spirit,'),
  ('299a57c6-192d-597d-aa0c-4eb845d68716', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 7, 7, 'so that you became an example to all who believe in Macedonia and in Achaia.'),
  ('773b73d1-f1f8-51d9-ab4c-4e82b2ffe3a8', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 8, 8, 'For from you the word of the Lord has been declared, not only in Macedonia and Achaia, but also in every place your faith toward God has gone out; so that we need not to say anything.'),
  ('e9b7e795-cb78-506f-a010-451d5863a583', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 9, 9, 'For they themselves report concerning us what kind of a reception we had from you; and how you turned to God from idols, to serve a living and true God,'),
  ('ea5be3d3-ad09-53ed-aa81-57dabab92f72', 'f06b3940-e878-5f5a-a868-1ceff30053b4', NULL, 10, 10, 'and to wait for his Son from heaven, whom he raised from the dead--Jesus, who delivers us from the wrath to come.'),
  ('a8b4a075-ae8d-5e69-a6b3-55fc46ec3bab', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 1, 1, 'For you yourselves know, brothers, our visit to you wasn''t in vain,'),
  ('65bf5430-7f48-519b-afff-2761811aeb7e', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 2, 2, 'but having suffered before and been shamefully treated, as you know, at Philippi, we grew bold in our God to tell you the Good News of God in much conflict.'),
  ('01a06d8d-606f-5d9b-a8e1-041fd6c13b3a', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 3, 3, 'For our exhortation is not of error, nor of uncleanness, nor in deception.'),
  ('00842c6c-5f89-5e16-ae79-331a2983127a', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 4, 4, 'But even as we have been approved by God to be entrusted with the Good News, so we speak; not as pleasing men, but God, who tests our hearts.'),
  ('fea9e27d-f912-5f3f-aa8f-c5e0de787069', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 5, 5, 'For neither were we at any time found using words of flattery, as you know, nor a cloak of covetousness (God is witness),'),
  ('0fa4f6f8-0b3f-56cc-a024-b544fd39f829', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 6, 6, 'nor seeking glory from men (neither from you nor from others), when we might have claimed authority as apostles of Christ.'),
  ('93f31504-841a-5a92-afaa-a829b17b43ab', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 7, 7, 'But we were gentle among you, like a nursing mother cherishes her own children.'),
  ('5dcf018b-d163-5661-a4e7-ca5722426bd8', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 8, 8, 'Even so, affectionately longing for you, we were well pleased to impart to you, not the Good News of God only, but also our own souls, because you had become very dear to us.'),
  ('186e0f9e-b3b5-561f-a5a0-879d864ebaf8', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 9, 9, 'For you remember, brothers, our labor and travail; for working night and day, that we might not burden any of you, we preached to you the Good News of God.'),
  ('0d7535ab-d146-592f-a733-101b1faeb56e', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 10, 10, 'You are witnesses with God, how holy, righteously, and blamelessly we behaved ourselves toward you who believe.'),
  ('52e7f552-f4cd-5a61-a89a-a18cac77cb14', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 11, 11, 'As you know, we exhorted, comforted, and implored every one of you, as a father does his own children,'),
  ('1cec64f4-5988-5798-a77e-15116169b6ea', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 12, 12, 'to the end that you should walk worthily of God, who calls you into his own Kingdom and glory.'),
  ('12071dec-51bb-596c-a3bb-dc797c554be7', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 13, 13, 'For this cause we also thank God without ceasing, that, when you received from us the word of the message of God, you accepted it not as the word of men, but, as it is in truth, the word of God, which also works in you who believe.'),
  ('cfffbbd3-1a7a-56d3-ad4a-825caa4e5dd5', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 14, 14, 'For you, brothers, became imitators of the assemblies of God which are in Judea in Christ Jesus; for you also suffered the same things from your own countrymen, even as they did from the Jews;'),
  ('d6b5df99-3341-51dd-a438-355899a28fdd', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 15, 15, 'who killed both the Lord Jesus and their own prophets, and drove us out, and didn''t please God, and are contrary to all men;'),
  ('4ce9d48e-442b-59b3-aa8c-f34bd150b5ee', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 16, 16, 'forbidding us to speak to the Gentiles that they may be saved; to fill up their sins always. But wrath has come on them to the uttermost.'),
  ('8b8fee4f-8592-5c43-ae41-c3e245bd0a42', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 17, 17, 'But we, brothers, being bereaved of you for a short season, in presence, not in heart, tried even harder to see your face with great desire,'),
  ('59090f08-a06f-5041-aa0a-cb8c28456041', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 18, 18, 'because we wanted to come to you--indeed, I, Paul, once and again--but Satan hindered us.'),
  ('5ee51508-a1cd-5fcb-a5ae-09b60b752273', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 19, 19, 'For what is our hope, or joy, or crown of rejoicing? Isn''t it even you, before our Lord Jesus at his coming?'),
  ('208618b6-b16d-5382-a694-bbb7df85e218', 'a11d87f3-989f-5c25-a44b-625671c129c4', NULL, 20, 20, 'For you are our glory and our joy.'),
  ('e8c7ecf2-c373-553d-a55d-b273a78f64ca', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 1, 1, 'Therefore, when we couldn''t stand it any longer, we thought it good to be left behind at Athens alone,'),
  ('da383f8f-8751-5975-a1b7-4cad28659d40', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 2, 2, 'and sent Timothy, our brother and God''s servant in the Good News of Christ, to establish you, and to comfort you concerning your faith;'),
  ('064497ac-23af-5ebd-a163-b660d79cb55b', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 3, 3, 'that no one be moved by these afflictions. For you know that we are appointed to this task.'),
  ('7908922c-7046-596d-ab49-a17547beca84', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 4, 4, 'For most certainly, when we were with you, we told you beforehand that we are to suffer affliction, even as it happened, and you know.'),
  ('dc61dba1-156b-5c2b-ae67-70221d857555', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 5, 5, 'For this cause I also, when I couldn''t stand it any longer, sent that I might know your faith, for fear that by any means the tempter had tempted you, and our labor would have been in vain.'),
  ('d2d5e627-5ec6-5dca-aa02-9b38715a4f89', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 6, 6, 'But when Timothy came just now to us from you, and brought us glad news of your faith and love, and that you have good memories of us always, longing to see us, even as we also long to see you;'),
  ('c7d9acc7-f401-5121-a7f9-6b45f5b21176', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 7, 7, 'for this cause, brothers, we were comforted over you in all our distress and affliction through your faith.'),
  ('bd147197-a617-5663-a697-a4530e0014ef', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 8, 8, 'For now we live, if you stand fast in the Lord.'),
  ('0d5c9f35-2e14-5035-a37e-6e10759adda5', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 9, 9, 'For what thanksgiving can we render again to God for you, for all the joy with which we rejoice for your sakes before our God;'),
  ('6b044692-89cb-562d-ab63-ab2f367e641a', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 10, 10, 'night and day praying exceedingly that we may see your face, and may perfect that which is lacking in your faith?'),
  ('f247d8f4-cbda-56e4-a006-1d0b392b4548', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 11, 11, 'Now may our God and Father himself, and our Lord Jesus Christ, direct our way to you;'),
  ('3c7bac08-5f90-5f0b-a412-c8c9f803d51c', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 12, 12, 'and the Lord make you to increase and abound in love one toward another, and toward all men, even as we also do toward you,'),
  ('625eee2d-877c-5125-a51d-8c73a4a2ab4c', 'aea18955-fcc4-59c3-ac19-70be93273b8a', NULL, 13, 13, 'to the end he may establish your hearts blameless in holiness before our God and Father, at the coming of our Lord Jesus with all his saints.'),
  ('2bc68c72-65f9-56f4-ae69-df940d76740d', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 1, 1, 'Finally then, brothers, we beg and exhort you in the Lord Jesus, that as you received from us how you ought to walk and to please God, that you abound more and more.'),
  ('b9ff3e1c-f043-5c96-a15a-bc27050e9735', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 2, 2, 'For you know what instructions we gave you through the Lord Jesus.'),
  ('e9d95ee9-1700-5ab5-a686-8b259b6572fd', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 3, 3, 'For this is the will of God: your sanctification, that you abstain from sexual immorality,'),
  ('ba7421b4-daf9-5516-aebf-3df031051404', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 4, 4, 'that each one of you know how to possess himself of his own vessel in sanctification and honor,'),
  ('3d51f41d-1553-573f-ab85-4e5b479998c4', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 5, 5, 'not in the passion of lust, even as the Gentiles who don''t know God;'),
  ('f0b9cd9c-bda6-5948-a25b-a1c466f053c9', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 6, 6, 'that no one should take advantage of and wrong a brother or sister in this matter; because the Lord is an avenger in all these things, as also we forewarned you and testified.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('290a4244-10f2-5bd7-aea4-881c11757a74', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 7, 7, 'For God called us not for uncleanness, but in sanctification.'),
  ('2655076f-2eb0-5838-a563-5b37cfcab07d', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 8, 8, 'Therefore he who rejects this doesn''t reject man, but God, who has also given his Holy Spirit to you.'),
  ('e35f6aed-bc66-5c71-a276-591d614da147', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 9, 9, 'But concerning brotherly love, you have no need that one write to you. For you yourselves are taught by God to love one another,'),
  ('1f2c2393-d52b-50af-aa63-bbb8ef4b94f0', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 10, 10, 'for indeed you do it toward all the brothers who are in all Macedonia. But we exhort you, brothers, that you abound more and more;'),
  ('28a337ed-4a77-5560-ab67-2fdf250df06b', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 11, 11, 'and that you make it your ambition to lead a quiet life, and to do your own business, and to work with your own hands, even as we instructed you;'),
  ('c9e320e0-2bb4-599e-a9b4-534be53f759a', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 12, 12, 'that you may walk properly toward those who are outside, and may have need of nothing.'),
  ('be8c50ed-53e2-5f1e-a717-490835a98d91', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 13, 13, 'But we don''t want you to be ignorant, brothers, concerning those who have fallen asleep, so that you don''t grieve like the rest, who have no hope.'),
  ('380bbf5c-462c-5b44-a4b0-57e11391d6d3', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 14, 14, 'For if we believe that Jesus died and rose again, even so God will bring with him those who have fallen asleep in Jesus.'),
  ('dc498b8c-725e-5317-ab75-7dbb79793b76', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 15, 15, 'For this we tell you by the word of the Lord, that we who are alive, who are left to the coming of the Lord, will in no way precede those who have fallen asleep.'),
  ('85c48364-82ae-5ce7-abcc-674011befeed', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 16, 16, 'For the Lord himself will descend from heaven with a shout, with the voice of the archangel, and with God''s trumpet. The dead in Christ will rise first,'),
  ('60aa6f31-25a1-542f-a349-14b595fa754b', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 17, 17, 'then we who are alive, who are left, will be caught up together with them in the clouds, to meet the Lord in the air. So we will be with the Lord forever.'),
  ('53385371-7916-5b50-aa6e-6d6de3f8208f', '8fd14c51-a46e-5766-a2e2-a356880b5321', NULL, 18, 18, 'Therefore comfort one another with these words.'),
  ('da6d3c16-e175-587a-a7e1-5cf9ccc40f2f', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 1, 1, 'But concerning the times and the seasons, brothers, you have no need that anything be written to you.'),
  ('e2984400-87ce-5976-a30a-20178e89879b', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 2, 2, 'For you yourselves know well that the day of the Lord comes like a thief in the night.'),
  ('593d04d3-cd2e-5e96-a3f1-b6e97517138a', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 3, 3, 'For when they are saying, "Peace and safety," then sudden destruction will come on them, like birth pains on a pregnant woman; and they will in no way escape.'),
  ('eacaf5ec-01f9-5c8c-ad0e-b619badce476', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 4, 4, 'But you, brothers, aren''t in darkness, that the day should overtake you like a thief.'),
  ('dcdb4509-9c3f-5483-a2ba-ee4523450df2', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 5, 5, 'You are all children of light, and children of the day. We don''t belong to the night, nor to darkness,'),
  ('1506686e-b26b-5084-ab3f-5b6e5307f95a', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 6, 6, 'so then let''s not sleep, as the rest do, but let''s watch and be sober.'),
  ('107e57d6-cce4-5aa6-a519-e18bf7d6afb3', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 7, 7, 'For those who sleep, sleep in the night, and those who are drunk are drunk in the night.'),
  ('5bb6658c-fa01-5122-a9fb-3f036218e876', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 8, 8, 'But let us, since we belong to the day, be sober, putting on the breastplate of faith and love, and, for a helmet, the hope of salvation.'),
  ('a247d2d7-90eb-5a9a-a538-e565adbae93d', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 9, 9, 'For God didn''t appoint us to wrath, but to the obtaining of salvation through our Lord Jesus Christ,'),
  ('77f8ded8-f633-5ce2-a822-f9ef3901f8e5', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 10, 10, 'who died for us, that, whether we wake or sleep, we should live together with him.'),
  ('0ab339ce-005f-523b-aace-c86c5a7e34da', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 11, 11, 'Therefore exhort one another, and build each other up, even as you also do.'),
  ('adddca93-f0b3-5ab9-a1e9-3edcb2d7a957', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 12, 12, 'But we beg you, brothers, to know those who labor among you, and are over you in the Lord, and admonish you,'),
  ('eccf402e-60b9-5610-a010-d1478d17bab0', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 13, 13, 'and to respect and honor them in love for their work''s sake. Be at peace among yourselves.'),
  ('17d139ec-3eb7-554f-af79-a3306d5a63b5', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 14, 14, 'We exhort you, brothers, admonish the disorderly, encourage the fainthearted, support the weak, be patient toward all.'),
  ('8449aa5e-bba1-5787-a452-121bb8fb68fa', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 15, 15, 'See that no one returns evil for evil to anyone, but always follow after that which is good, for one another, and for all.'),
  ('44d4c9dc-76e3-5429-a948-62e05867c2f1', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 16, 16, 'Rejoice always.'),
  ('67b43fab-3056-56b8-a6d1-12a613e2df98', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 17, 17, 'Pray without ceasing.'),
  ('5f351434-0c06-53ae-ab00-5b4d77aea1dc', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 18, 18, 'In everything give thanks, for this is the will of God in Christ Jesus toward you.'),
  ('4cde01f2-4b71-53a5-accc-0ed79e6ab7d3', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 19, 19, 'Don''t quench the Spirit.'),
  ('dd89a052-cb35-5d58-a8a6-e3a915dd745b', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 20, 20, 'Don''t despise prophesies.'),
  ('01849c4e-6648-5037-a47c-842fa58359c4', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 21, 21, 'Test all things, and hold firmly that which is good.'),
  ('8477a6c1-753b-5313-a0fe-69b122008008', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 22, 22, 'Abstain from every form of evil.'),
  ('5c204f2b-4b23-5b73-a2cd-5d7a3bccc659', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 23, 23, 'May the God of peace himself sanctify you completely. May your whole spirit, soul, and body be preserved blameless at the coming of our Lord Jesus Christ.'),
  ('d2d89caf-7926-5f19-a7a8-c954d77f8cc9', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 24, 24, 'He who calls you is faithful, who will also do it.'),
  ('b6363fb3-cf3d-5101-a99d-fe70507eea1b', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 25, 25, 'Brothers, pray for us.'),
  ('7483ffba-5012-5479-a7f0-5383458e0960', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 26, 26, 'Greet all the brothers with a holy kiss.'),
  ('9489b5eb-787e-5976-afbf-b1895cb2f2ca', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 27, 27, 'I solemnly command you by the Lord that this letter be read to all the holy brothers.'),
  ('3dfd1d92-2845-52d9-ab2d-cbb650ec4932', 'ba756015-ae45-5e94-a7ec-5dceb38b3947', NULL, 28, 28, 'The grace of our Lord Jesus Christ be with you. Amen.'),
  ('6c5024e1-65eb-5d20-a1ec-fdae5cad3281', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 1, 1, 'Paul, Silvanus, and Timothy, to the assembly of the Thessalonians in God our Father, and the Lord Jesus Christ:'),
  ('3d1988b9-7110-5fcf-a473-929b6f0fefcb', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 2, 2, 'Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('6328968c-24c0-5055-a163-40211d303b52', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 3, 3, 'We are bound to always give thanks to God for you, brothers, even as it is appropriate, because your faith grows exceedingly, and the love of each and every one of you towards one another abounds;'),
  ('53d0eba6-a0e6-5780-a3fb-da998bfa8d93', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 4, 4, 'so that we ourselves boast about you in the assemblies of God for your patience and faith in all your persecutions and in the afflictions which you endure.'),
  ('356a0e7a-16ac-5c76-a51b-19a88afd08e0', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 5, 5, 'This is an obvious sign of the righteous judgment of God, to the end that you may be counted worthy of the Kingdom of God, for which you also suffer.'),
  ('d93084ce-1068-5ed6-a770-db7df76ddcd2', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 6, 6, 'Since it is a righteous thing with God to repay affliction to those who afflict you,'),
  ('6a94ab0f-981c-58c3-a67e-5398e47a4770', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 7, 7, 'and to give relief to you who are afflicted with us, when the Lord Jesus is revealed from heaven with his mighty angels in flaming fire,'),
  ('4161f36e-2d57-5797-a57d-6a3f058e8142', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 8, 8, 'giving vengeance to those who don''t know God, and to those who don''t obey the Good News of our Lord Jesus,'),
  ('d6d4be36-dc5f-5005-a8d0-6fdb669fca43', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 9, 9, 'who will pay the penalty: eternal destruction from the face of the Lord and from the glory of his might,'),
  ('b841889b-2f13-5565-a8fa-d6d3d178b7dd', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 10, 10, 'when he comes to be glorified in his saints, and to be admired among all those who have believed (because our testimony to you was believed) in that day.'),
  ('e7ab683a-ebf6-5120-a30d-3e97a8db0634', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 11, 11, 'To this end we also pray always for you, that our God may count you worthy of your calling, and fulfill every desire of goodness and work of faith, with power;'),
  ('fa19ff96-d2e4-54a9-ac92-f2684f64c144', '8c4f52c5-1266-5156-a171-f7ea85e0c452', NULL, 12, 12, 'that the name of our Lord Jesus may be glorified in you, and you in him, according to the grace of our God and the Lord Jesus Christ.'),
  ('1110e954-b91e-5dd1-a384-6021624bc19d', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 1, 1, 'Now, brothers, concerning the coming of our Lord Jesus Christ, and our gathering together to him, we ask you'),
  ('8a35baf7-db8f-5363-ae6c-893297f68350', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 2, 2, 'not to be quickly shaken in your mind, nor yet be troubled, either by spirit, or by word, or by letter as from us, saying that the day of Christ had come.'),
  ('353121a0-1236-5449-a1ab-1f4104059eec', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 3, 3, 'Let no one deceive you in any way. For it will not be, unless the departure comes first, and the man of sin is revealed, the son of destruction,'),
  ('d4c5d259-0460-5428-a347-9664cc113940', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 4, 4, 'he who opposes and exalts himself against all that is called God or that is worshiped; so that he sits as God in the temple of God, setting himself up as God.'),
  ('ad327d06-4f3e-5443-a97b-c1abded5ea8d', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 5, 5, 'Don''t you remember that, when I was still with you, I told you these things?'),
  ('fdc3e819-4a3b-542d-ae41-d38808092deb', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 6, 6, 'Now you know what is restraining him, to the end that he may be revealed in his own season.'),
  ('37043dd0-bd27-5258-a044-8cf47ccc6232', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 7, 7, 'For the mystery of lawlessness already works. Only there is one who restrains now, until he is taken out of the way.'),
  ('53ec5a62-1cce-57c0-a061-684bb8411014', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 8, 8, 'Then the lawless one will be revealed, whom the Lord will kill with the breath of his mouth, and destroy by the manifestation of his coming;'),
  ('521ddf31-327e-5a8c-abb5-6b5f432d99fc', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 9, 9, 'even he whose coming is according to the working of Satan with all power and signs and lying wonders,'),
  ('23cc35d5-2f38-5e6a-a788-cca664f2e101', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 10, 10, 'and with all deception of wickedness for those who are being lost, because they didn''t receive the love of the truth, that they might be saved.'),
  ('8daf588a-ce59-5b99-a256-b0c3131643e0', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 11, 11, 'Because of this, God sends them a working of error, that they should believe a lie;'),
  ('c35e8a65-2ed4-5df1-a793-333d945df53e', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 12, 12, 'that they all might be judged who didn''t believe the truth, but had pleasure in unrighteousness.'),
  ('f2ee168e-15b3-53b6-aec6-6d1dadc161a4', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 13, 13, 'But we are bound to always give thanks to God for you, brothers loved by the Lord, because God chose you from the beginning for salvation through sanctification of the Spirit and belief in the truth;'),
  ('56736955-b410-5be7-a4d6-c644d01c2a4d', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 14, 14, 'to which he called you through our Good News, for the obtaining of the glory of our Lord Jesus Christ.'),
  ('f3daef72-a587-574b-a7ad-950cc943825f', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 15, 15, 'So then, brothers, stand firm, and hold the traditions which you were taught by us, whether by word, or by letter.'),
  ('25e33a3f-4370-5db3-ac1a-589aa5fe6cb1', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 16, 16, 'Now our Lord Jesus Christ himself, and God our Father, who loved us and gave us eternal comfort and good hope through grace,'),
  ('72375adc-0be1-5f85-ad91-98957f716c28', '45bcd308-19a6-56ea-abcc-7a2565da3439', NULL, 17, 17, 'comfort your hearts and establish you in every good work and word.'),
  ('2c891802-6326-53e5-a316-ce1c5a70f06c', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 1, 1, 'Finally, brothers, pray for us, that the word of the Lord may spread rapidly and be glorified, even as also with you;'),
  ('f7a98275-bcd7-5c17-aba1-17f756fd8d1a', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 2, 2, 'and that we may be delivered from unreasonable and evil men; for not all have faith.'),
  ('d664ecb3-7fb7-56c6-a8b6-9c4235067979', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 3, 3, 'But the Lord is faithful, who will establish you, and guard you from the evil one.'),
  ('460ab202-f2a9-59f6-acda-ef7b09f80a81', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 4, 4, 'We have confidence in the Lord concerning you, that you both do and will do the things we command.'),
  ('6e095fc1-9073-5013-a8cc-f561870c19e4', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 5, 5, 'May the Lord direct your hearts into the love of God, and into the patience of Christ.'),
  ('6deaa45a-4657-5069-a095-43bbad444f7c', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 6, 6, 'Now we command you, brothers, in the name of our Lord Jesus Christ, that you withdraw yourselves from every brother who walks in rebellion, and not after the tradition which they received from us.'),
  ('f3bcc5bc-180c-569e-a151-24255ff534ec', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 7, 7, 'For you know how you ought to imitate us. For we didn''t behave ourselves rebelliously among you,'),
  ('6dc968ba-8e35-509a-a072-dc7163ec786d', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 8, 8, 'neither did we eat bread from anyone''s hand without paying for it, but in labor and travail worked night and day, that we might not burden any of you;'),
  ('3d5e727e-db95-5432-a575-d5e2e3a447b4', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 9, 9, 'not because we don''t have the right, but to make ourselves an example to you, that you should imitate us.'),
  ('706786cb-5cba-5a28-ab3a-427643367096', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 10, 10, 'For even when we were with you, we commanded you this: "If anyone will not work, neither let him eat."'),
  ('bed44d8d-4bd9-564b-a47e-5475517a73fe', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 11, 11, 'For we hear of some who walk among you in rebellion, who don''t work at all, but are busybodies.'),
  ('e96fb58a-46bc-53d1-a752-4a857a7f1d93', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 12, 12, 'Now those who are that way, we command and exhort in the Lord Jesus Christ, that with quietness they work, and eat their own bread.'),
  ('0d87f583-93af-56b7-a687-58b28cec32ef', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 13, 13, 'But you, brothers, don''t be weary in doing well.'),
  ('8296e451-bdb2-5f55-a406-cd30f2d93356', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 14, 14, 'If any man doesn''t obey our word in this letter, note that man, that you have no company with him, to the end that he may be ashamed.'),
  ('9141e6aa-c35f-5d9a-a1db-b102e02db680', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 15, 15, 'Don''t count him as an enemy, but admonish him as a brother.'),
  ('e4a4a07b-f8c7-54fd-a960-fcb31b1f7821', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 16, 16, 'Now may the Lord of peace himself give you peace at all times in all ways. The Lord be with you all.'),
  ('072019ed-dc9d-5737-a0ab-6734c705cfff', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 17, 17, 'The greeting of me, Paul, with my own hand, which is the sign in every letter: this is how I write.'),
  ('4b245a05-b467-5dff-aed0-dcb36b5162f8', '1347c2db-7a5a-5cab-a19c-95b99bf69f2b', NULL, 18, 18, 'The grace of our Lord Jesus Christ be with you all. Amen.'),
  ('ed479aeb-b633-54a5-a903-1a58eaaca0b1', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 1, 1, 'Paul, an apostle of Christ Jesus according to the commandment of God our Savior, and Christ Jesus our hope;'),
  ('bbed5cd9-f0a6-5450-a267-309043cba280', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 2, 2, 'to Timothy, my true child in faith: Grace, mercy, and peace, from God our Father and Christ Jesus our Lord.'),
  ('dcbc89e8-57dc-5cea-afcc-31d110debc10', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 3, 3, 'As I urged you when I was going into Macedonia, stay at Ephesus that you might command certain men not to teach a different doctrine,'),
  ('6c45385c-83cf-5737-a444-ddcf4d431ac1', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 4, 4, 'neither to pay attention to myths and endless genealogies, which cause disputes, rather than God''s stewardship, which is in faith--'),
  ('732ab096-bcbf-5b79-aeab-eed3b877eb54', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 5, 5, 'but the goal of this command is love, out of a pure heart and a good conscience and sincere faith;'),
  ('22724260-10e3-5f6b-abb1-ef2261990822', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 6, 6, 'from which things some, having missed the mark, have turned aside to vain talking;'),
  ('2a916f1f-d4c7-5f9a-aea6-2dbff35b73d0', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 7, 7, 'desiring to be teachers of the law, though they understand neither what they say, nor about what they strongly affirm.'),
  ('b3a6089d-6737-56be-ae6c-449f54c4d2ae', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 8, 8, 'But we know that the law is good, if a man uses it lawfully,'),
  ('f058a51a-dc3a-508c-a016-5e34fa818dea', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 9, 9, 'as knowing this, that law is not made for a righteous man, but for the lawless and insubordinate, for the ungodly and sinners, for the unholy and profane, for murderers of fathers and murderers of mothers, for manslayers,'),
  ('9bf6fad6-1470-5e9e-a07c-7b29c7fe4a74', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 10, 10, 'for the sexually immoral, for homosexuals, for slave-traders, for liars, for perjurers, and for any other thing contrary to the sound doctrine;'),
  ('7a4dee79-cdc6-59c9-aabd-6cae1e2ac20a', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 11, 11, 'according to the Good News of the glory of the blessed God, which was committed to my trust.'),
  ('255d8ae6-60c0-5648-a7d0-f9adb1dbcc2c', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 12, 12, 'And I thank him who enabled me, Christ Jesus our Lord, because he counted me faithful, appointing me to service;'),
  ('4edaa636-6747-5147-ae6d-52d70b0bcf9e', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 13, 13, 'although I was before a blasphemer, a persecutor, and insolent. However, I obtained mercy, because I did it ignorantly in unbelief.'),
  ('23e05e1e-356c-5ca4-a798-746f28bf782e', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 14, 14, 'The grace of our Lord abounded exceedingly with faith and love which is in Christ Jesus.'),
  ('45a10fe5-460d-50c5-af4a-538476ee8684', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 15, 15, 'The saying is faithful and worthy of all acceptance, that Christ Jesus came into the world to save sinners; of whom I am chief.'),
  ('383d253a-c2ac-50a7-a5b7-9d0512c79a26', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 16, 16, 'However, for this cause I obtained mercy, that in me first, Jesus Christ might display all his patience, for an example of those who were going to believe in him for eternal life.'),
  ('1a8e5f11-725a-5741-a3f2-73db8dc277a8', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 17, 17, 'Now to the King eternal, immortal, invisible, to God who alone is wise, be honor and glory forever and ever. Amen.'),
  ('475bd3c0-0b03-5885-af09-411136e82623', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 18, 18, 'This instruction I commit to you, my child Timothy, according to the prophecies which led the way to you, that by them you may wage the good warfare;'),
  ('2aa3acb6-a5b7-5ced-a01f-07b1bcd7212e', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 19, 19, 'holding faith and a good conscience; which some having thrust away made a shipwreck concerning the faith;'),
  ('9cc9b786-9709-561f-ae09-7bbdddee87cc', '3f91db37-9116-5130-a6e3-8e58101c0171', NULL, 20, 20, 'of whom is Hymenaeus and Alexander; whom I delivered to Satan, that they might be taught not to blaspheme.'),
  ('6b566b2e-9568-5dfe-a48a-06805bd4f083', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 1, 1, 'I exhort therefore, first of all, that petitions, prayers, intercessions, and givings of thanks, be made for all men:'),
  ('92f2cc8e-238d-5824-a9b9-5e93a3232351', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 2, 2, 'for kings and all who are in high places; that we may lead a tranquil and quiet life in all godliness and reverence.'),
  ('f967b178-1f45-54e4-a511-faced822db92', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 3, 3, 'For this is good and acceptable in the sight of God our Savior;'),
  ('b7b219a8-637c-59af-a575-c21c977059d8', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 4, 4, 'who desires all people to be saved and come to full knowledge of the truth.'),
  ('c28a7001-5292-519e-a13f-bec1dbd955a8', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 5, 5, 'For there is one God, and one mediator between God and men, the man Christ Jesus,'),
  ('ebea35d2-77c6-558f-a279-4d1dfd329eac', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 6, 6, 'who gave himself as a ransom for all; the testimony in its own times;'),
  ('b6b440cf-09e0-5fb1-a959-da0dbd62db35', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 7, 7, 'to which I was appointed a preacher and an apostle (I am telling the truth in Christ, not lying), a teacher of the Gentiles in faith and truth.'),
  ('d5a2da86-2de9-58cc-a73f-38e06b3a89d7', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 8, 8, 'I desire therefore that the men in every place pray, lifting up holy hands without anger and doubting.'),
  ('2e4c55bd-e26b-54f4-a818-2e9105f523a5', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 9, 9, 'In the same way, that women also adorn themselves in decent clothing, with modesty and propriety; not just with braided hair, gold, pearls, or expensive clothing;'),
  ('a938499a-e957-5306-adc8-233e4c1f622d', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 10, 10, 'but (which becomes women professing godliness) with good works.'),
  ('209106af-2723-5dc8-a3bb-205c433d8670', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 11, 11, 'Let a woman learn in quietness with all subjection.'),
  ('5bd0819b-2969-5683-a90f-2285cb24e486', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 12, 12, 'But I don''t permit a woman to teach, nor to exercise authority over a man, but to be in quietness.'),
  ('f24e816e-7a6e-5849-abd1-b01cb6758bb4', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 13, 13, 'For Adam was first formed, then Eve.'),
  ('3dadde1f-016e-5fb5-a130-1e74838ecdd5', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 14, 14, 'Adam wasn''t deceived, but the woman, being deceived, has fallen into disobedience;'),
  ('f6d1284e-67fa-56d7-ad57-d3fb493899e2', '096c1617-6365-5645-a3dc-a552a11725d1', NULL, 15, 15, 'but she will be saved through her childbearing, if they continue in faith, love, and sanctification with sobriety.'),
  ('4cb1d026-5665-50df-a150-357dd1224f43', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 1, 1, 'This is a faithful saying: if a man seeks the office of an overseer, he desires a good work.'),
  ('99721671-3d84-5856-a612-37e88f0254f0', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 2, 2, 'The overseer therefore must be without reproach, the husband of one wife, temperate, sensible, modest, hospitable, good at teaching;'),
  ('038fec12-77b8-5340-a4ef-6e3f41641ecc', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 3, 3, 'not a drinker, not violent, not greedy for money, but gentle, not quarrelsome, not covetous;'),
  ('344c3e19-ae4e-5219-ae60-bd1c09d86fd1', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 4, 4, 'one who rules his own house well, having children in subjection with all reverence;'),
  ('1a018c03-481d-580e-a8d3-86a3f6074d7c', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 5, 5, '(but if a man doesn''t know how to rule his own house, how will he take care of the assembly of God?)'),
  ('9836ec3f-ffd3-55cc-acc4-17cf8fb353f1', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 6, 6, 'not a new convert, lest being puffed up he fall into the same condemnation as the devil.'),
  ('8171b6b7-0131-5c7d-a227-0bb2d94053c4', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 7, 7, 'Moreover he must have good testimony from those who are outside, to avoid falling into reproach and the snare of the devil.'),
  ('ecf41a9c-828c-54a1-a852-9711f5692731', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 8, 8, 'Servants, in the same way, must be reverent, not double-tongued, not addicted to much wine, not greedy for money;'),
  ('759a4957-609a-5e0d-aace-291d40e082c0', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 9, 9, 'holding the mystery of the faith in a pure conscience.'),
  ('d2d4c11b-2f03-5dd5-a9f6-7f67f8637aa9', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 10, 10, 'Let them also first be tested; then let them serve if they are blameless.'),
  ('a8105327-04a4-5c5a-a237-a29d43330349', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 11, 11, 'Their wives in the same way must be reverent, not slanderers, temperate, faithful in all things.'),
  ('b5f8d1f8-6edd-5b04-a990-9275637b2f48', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 12, 12, 'Let servants be husbands of one wife, ruling their children and their own houses well.'),
  ('b150064a-4e2b-5344-a81d-f23b9ddb5fde', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 13, 13, 'For those who have served well gain for themselves a good standing, and great boldness in the faith which is in Christ Jesus.'),
  ('4423549d-332c-5c7b-a06f-f982a767b4b2', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 14, 14, 'These things I write to you, hoping to come to you shortly;'),
  ('7347fd43-8a40-5f0f-a85d-062253499eab', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 15, 15, 'but if I wait long, that you may know how men ought to behave themselves in the house of God, which is the assembly of the living God, the pillar and ground of the truth.'),
  ('fcc31fc1-0938-5983-af26-517ef185213d', 'a8297aa6-aa9e-5a25-ab5e-2a276e7f76ca', NULL, 16, 16, 'Without controversy, the mystery of godliness is great: God was revealed in the flesh, justified in the spirit, seen by angels, preached among the nations, believed on in the world, and received up in glory.'),
  ('b91a51da-4100-56d1-a298-5452fc55e823', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 1, 1, 'But the Spirit says expressly that in later times some will fall away from the faith, paying attention to seducing spirits and doctrines of demons,'),
  ('f0f833d4-c4f9-57b6-a874-032a1ff8b12a', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 2, 2, 'through the hypocrisy of men who speak lies, branded in their own conscience as with a hot iron;'),
  ('326f1a63-c32f-5895-aee3-71b8e290b579', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 3, 3, 'forbidding marriage and commanding to abstain from foods which God created to be received with thanksgiving by those who believe and know the truth.'),
  ('734f717d-5bf2-548f-a773-c40c9225f8ca', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 4, 4, 'For every creature of God is good, and nothing is to be rejected, if it is received with thanksgiving.'),
  ('760d805f-fe40-525a-a824-de975d6d3cff', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 5, 5, 'For it is sanctified through the word of God and prayer.'),
  ('5478e14b-c1f9-5332-a7ca-40cca3b841e3', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 6, 6, 'If you instruct the brothers of these things, you will be a good servant of Christ Jesus, nourished in the words of the faith, and of the good doctrine which you have followed.'),
  ('549cc77f-7087-52a4-a427-0ec519c3a519', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 7, 7, 'But refuse profane and old wives'' fables. Exercise yourself toward godliness.'),
  ('282aaaa7-def1-54fc-ab9e-79654976fde9', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 8, 8, 'For bodily exercise has some value, but godliness has value in all things, having the promise of the life which is now, and of that which is to come.'),
  ('58800245-7492-5c7c-a7f9-a1e5a04ab8f3', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 9, 9, 'This saying is faithful and worthy of all acceptance.'),
  ('423a311d-3a36-51ef-a328-d383ebb9a375', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 10, 10, 'For to this end we both labor and suffer reproach, because we have set our trust in the living God, who is the Savior of all men, especially of those who believe.'),
  ('9779cd30-54e2-5383-a91d-e5072a721caf', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 11, 11, 'Command and teach these things.'),
  ('d2396455-715e-5bc4-a657-af6a8bfc9ee0', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 12, 12, 'Let no man despise your youth; but be an example to those who believe, in word, in your way of life, in love, in spirit, in faith, and in purity.'),
  ('ccf2bb03-680e-5594-a53a-dd8bfb16b7ed', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 13, 13, 'Until I come, pay attention to reading, to exhortation, and to teaching.'),
  ('6fc34244-b191-58d9-a346-188e0b5732ae', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 14, 14, 'Don''t neglect the gift that is in you, which was given to you by prophecy, with the laying on of the hands of the elders.'),
  ('9320ed7c-ea63-55e8-aff9-69b5dfd69343', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 15, 15, 'Be diligent in these things. Give yourself wholly to them, that your progress may be revealed to all.'),
  ('6feb04b3-4944-5e11-ae51-0e89c6d6f23e', '966879a7-7bc3-5f56-ac02-e71273627db5', NULL, 16, 16, 'Pay attention to yourself, and to your teaching. Continue in these things, for in doing this you will save both yourself and those who hear you.'),
  ('a955348b-b364-552e-aacb-054faae12106', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 1, 1, 'Don''t rebuke an older man, but exhort him as a father; the younger men as brothers;'),
  ('d6a3d212-8f08-5ed3-aebd-03e525d48882', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 2, 2, 'the elder women as mothers; the younger as sisters, in all purity.'),
  ('8d6021fa-d003-5e55-a65a-47b572779b24', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 3, 3, 'Honor widows who are widows indeed.'),
  ('84b9377c-7b81-5bb5-a12d-0906c7f9d47f', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 4, 4, 'But if any widow has children or grandchildren, let them learn first to show piety towards their own family, and to repay their parents, for this is acceptable in the sight of God.'),
  ('6ea71b04-2b60-50e1-a4fe-5c49470e0814', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 5, 5, 'Now she who is a widow indeed, and desolate, has her hope set on God, and continues in petitions and prayers night and day.'),
  ('1b77f25d-b66f-55f8-a13e-00bb6ead1d15', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 6, 6, 'But she who gives herself to pleasure is dead while she lives.'),
  ('cb20047d-ebf4-5a94-a45c-45115c965a50', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 7, 7, 'Also command these things, that they may be without reproach.'),
  ('9e6d7222-0fca-5df1-a31d-b802ce736ff9', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 8, 8, 'But if anyone doesn''t provide for his own, and especially his own household, he has denied the faith, and is worse than an unbeliever.'),
  ('26cd01f0-f3f3-5d29-ac07-3dfc0d762b81', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 9, 9, 'Let no one be enrolled as a widow under sixty years old, having been the wife of one man,'),
  ('259c072d-c9d3-51e9-a910-abb1795b8bb9', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 10, 10, 'being approved by good works, if she has brought up children, if she has been hospitable to strangers, if she has washed the saints'' feet, if she has relieved the afflicted, and if she has diligently followed every good work.'),
  ('99cbb0f2-2dab-588d-abc9-6fd71b7b7488', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 11, 11, 'But refuse younger widows, for when they have grown wanton against Christ, they desire to marry;'),
  ('d515adee-a895-513a-a52c-d279e70007bf', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 12, 12, 'having condemnation, because they have rejected their first pledge.'),
  ('24ab0fa1-76d5-5bb0-ae51-6bd5a6081b31', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 13, 13, 'Besides, they also learn to be idle, going about from house to house. Not only idle, but also gossips and busybodies, saying things which they ought not.'),
  ('cf9c0c71-fa0b-5342-a347-43fb2925aaf9', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 14, 14, 'I desire therefore that the younger widows marry, bear children, rule the household, and give no occasion to the adversary for insulting.'),
  ('91c498ea-b61c-5a89-a1d4-a47fdf6452bf', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 15, 15, 'For already some have turned aside after Satan.'),
  ('60f4e04c-93e1-5bec-a8a7-56281885b426', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 16, 16, 'If any man or woman who believes has widows, let them relieve them, and don''t let the assembly be burdened; that it might relieve those who are widows indeed.'),
  ('261584c5-f9ff-51c2-af4d-c987b21e19d3', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 17, 17, 'Let the elders who rule well be counted worthy of double honor, especially those who labor in the word and in teaching.'),
  ('c082e720-a6fd-5cfb-a5cd-629b9e059b11', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 18, 18, 'For the Scripture says, "You shall not muzzle the ox when it treads out the grain." And, "The laborer is worthy of his wages."'),
  ('f0229f61-53e7-5494-a9f2-84407800c4ec', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 19, 19, 'Don''t receive an accusation against an elder, except at the word of two or three witnesses.'),
  ('e3710784-c554-5fe9-a42d-0de5d4dde9af', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 20, 20, 'Those who sin, reprove in the sight of all, that the rest also may be in fear.'),
  ('7bf1e995-5c0c-5c21-a050-03e4f5b8d9e7', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 21, 21, 'I command you in the sight of God, and Christ Jesus, and the chosen angels, that you observe these things without prejudice, doing nothing by partiality.'),
  ('e68be422-7068-5991-abb2-9a4460da5d15', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 22, 22, 'Lay hands hastily on no one, neither be a participant in other men''s sins. Keep yourself pure.'),
  ('623ad220-c949-566a-a7d7-0e368c1b69c6', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 23, 23, 'Be no longer a drinker of water only, but use a little wine for your stomach''s sake and your frequent infirmities.'),
  ('1b2a6d75-6ab3-5d10-af1a-4187fd0fa494', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 24, 24, 'Some men''s sins are evident, preceding them to judgment, and some also follow later.'),
  ('de7f64f2-5308-5e75-a4fd-10d772ef8496', 'df188627-1c92-512e-a56f-66135e40814e', NULL, 25, 25, 'In the same way also there are good works that are obvious, and those that are otherwise can''t be hidden.'),
  ('2b2a77f5-dc94-5d4b-a577-cec4110e6682', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 1, 1, 'Let as many as are bondservants under the yoke count their own masters worthy of all honor, that the name of God and the doctrine not be blasphemed.'),
  ('83762b05-0122-53ed-a3b5-be944af082f2', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 2, 2, 'Those who have believing masters, let them not despise them, because they are brothers, but rather let them serve them, because those who partake of the benefit are believing and beloved. Teach and exhort these things.'),
  ('948a81f0-5c83-5574-abaa-3cfe48914201', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 3, 3, 'If anyone teaches a different doctrine, and doesn''t consent to sound words, the words of our Lord Jesus Christ, and to the doctrine which is according to godliness,'),
  ('ed512aad-f85a-5545-af3f-1e1013a7168c', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 4, 4, 'he is conceited, knowing nothing, but obsessed with arguments, disputes, and word battles, from which come envy, strife, insulting, evil suspicions,'),
  ('b4497865-a5a4-52e7-a68d-20e409d20e1b', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 5, 5, 'constant friction of people of corrupt minds and destitute of the truth, who suppose that godliness is a means of gain. Withdraw yourself from such.'),
  ('13b77708-b0f2-5ab5-a297-8f37b4da15ae', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 6, 6, 'But godliness with contentment is great gain.'),
  ('888a284d-22eb-564d-ae9d-56a437781f33', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 7, 7, 'For we brought nothing into the world, and we certainly can''t carry anything out.'),
  ('afedcba6-7f95-576b-ab36-4f81efb993b2', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 8, 8, 'But having food and clothing, we will be content with that.'),
  ('bd7c53d9-ae28-5828-a94f-f786a1010a60', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 9, 9, 'But those who are determined to be rich fall into a temptation and a snare and many foolish and harmful lusts, such as drown men in ruin and destruction.'),
  ('7db0eb22-3b61-56c9-a1e2-303d3d3926b3', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 10, 10, 'For the love of money is a root of all kinds of evil. Some have been led astray from the faith in their greed, and have pierced themselves through with many sorrows.'),
  ('b08667cf-acf0-57cc-afa4-a75bccf97584', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 11, 11, 'But you, man of God, flee these things, and follow after righteousness, godliness, faith, love, patience, and gentleness.'),
  ('f3dc7c3b-b859-5657-a12f-9ee15518ab97', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 12, 12, 'Fight the good fight of faith. Lay hold of the eternal life to which you were called, and you confessed the good confession in the sight of many witnesses.'),
  ('bec2684b-f3ed-518a-abec-76885efef692', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 13, 13, 'I command you before God, who gives life to all things, and before Christ Jesus, who before Pontius Pilate testified the good confession,'),
  ('ac74f5c8-ba3b-5781-a111-de8d77973c51', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 14, 14, 'that you keep the commandment without spot, blameless, until the appearing of our Lord Jesus Christ;'),
  ('7c100a2e-d3f1-5077-ac7f-a2769a2a376b', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 15, 15, 'which in its own times he will show, who is the blessed and only Ruler, the King of kings, and Lord of lords;'),
  ('75345ba6-e5ca-503f-ae85-176e710167d3', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 16, 16, 'who alone has immortality, dwelling in unapproachable light; whom no man has seen, nor can see: to whom be honor and eternal power. Amen.'),
  ('13849038-6e95-57bc-ac2e-9cbb21eccf11', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 17, 17, 'Charge those who are rich in this present world that they not be haughty, nor have their hope set on the uncertainty of riches, but on the living God, who richly provides us with everything to enjoy;'),
  ('27b91666-d803-5883-a1ba-58f4e35d0566', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 18, 18, 'that they do good, that they be rich in good works, that they be ready to distribute, willing to communicate;'),
  ('2cc21faf-0976-5e75-a184-ad71ebf09fea', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 19, 19, 'laying up in store for themselves a good foundation against the time to come, that they may lay hold of eternal life.'),
  ('62ab5020-9f9d-546a-a6fe-ec2cb4b80671', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 20, 20, 'Timothy, guard that which is committed to you, turning away from the empty chatter and oppositions of the knowledge which is falsely so called;'),
  ('ee602bb3-660e-5aec-a045-0ebbe9dba62a', '41e9a116-20fb-5442-a59a-b425a30fb40f', NULL, 21, 21, 'which some professing have erred concerning the faith. Grace be with you. Amen.'),
  ('974cbde1-6d31-527d-adc1-314dbce14db4', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 1, 1, 'Paul, an apostle of Jesus Christ through the will of God, according to the promise of the life which is in Christ Jesus,'),
  ('741c2b5b-ea66-5356-a7c3-646245bb784b', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 2, 2, 'to Timothy, my beloved child: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord.'),
  ('43b38ed8-cdc5-5f47-a92a-9f44ba347caf', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 3, 3, 'I thank God, whom I serve as my forefathers did, with a pure conscience. How unceasing is my memory of you in my petitions, night and day'),
  ('94c9d189-982c-53d4-a498-d228eeb01e50', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 4, 4, 'longing to see you, remembering your tears, that I may be filled with joy;'),
  ('2a267318-38a6-5314-a3e9-e3e84a2e1de2', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 5, 5, 'having been reminded of the sincere faith that is in you; which lived first in your grandmother Lois, and your mother Eunice, and, I am persuaded, in you also.'),
  ('4a8b15a1-ad00-54ba-aa67-ec0f68c20ab9', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 6, 6, 'For this cause, I remind you that you should stir up the gift of God which is in you through the laying on of my hands.'),
  ('42cef8fb-cb5e-5bdb-ac20-6cb1869cbe4a', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 7, 7, 'For God didn''t give us a spirit of fear, but of power, love, and self-control.'),
  ('fd3bd520-4e9d-5882-a356-2b224a22586d', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 8, 8, 'Therefore don''t be ashamed of the testimony of our Lord, nor of me his prisoner; but endure hardship for the Good News according to the power of God,'),
  ('e5232d3d-7d65-56b8-aef5-224b9e8ec084', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 9, 9, 'who saved us and called us with a holy calling, not according to our works, but according to his own purpose and grace, which was given to us in Christ Jesus before times eternal,'),
  ('b44680e5-211e-5970-a5be-c9fd09fc7004', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 10, 10, 'but has now been revealed by the appearing of our Savior, Christ Jesus, who abolished death, and brought life and immortality to light through the Good News.'),
  ('0d988ca1-32e5-5d94-adc1-15e067c261f0', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 11, 11, 'For this, I was appointed as a preacher, an apostle, and a teacher of the Gentiles.'),
  ('a0847449-1371-519a-a87b-f90923b954e1', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 12, 12, 'For this cause I also suffer these things. Yet I am not ashamed, for I know him whom I have believed, and I am persuaded that he is able to guard that which I have committed to him against that day.'),
  ('45a9e39d-c482-5432-afa5-15732405d992', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 13, 13, 'Hold the pattern of sound words which you have heard from me, in faith and love which is in Christ Jesus.'),
  ('cf4fb05a-ffcd-5a59-af54-dfe65307ae56', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 14, 14, 'That good thing which was committed to you, guard through the Holy Spirit who dwells in us.'),
  ('5ac7be97-10ca-5672-abd0-e385af88242d', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 15, 15, 'This you know, that all who are in Asia turned away from me; of whom are Phygelus and Hermogenes.'),
  ('833f78ac-26a9-53e8-a842-3773c3392794', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 16, 16, 'May the Lord grant mercy to the house of Onesiphorus, for he often refreshed me, and was not ashamed of my chain,'),
  ('5680556d-ac7c-5077-ae4b-a7c9cbd252af', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 17, 17, 'but when he was in Rome, he sought me diligently, and found me'),
  ('2020b536-bd31-532c-ae69-4ecca309b205', '6c001f77-3d2a-5bc9-a3d8-bf2abe454ce6', NULL, 18, 18, '(the Lord grant to him to find the Lord''s mercy in that day); and in how many things he served at Ephesus, you know very well.'),
  ('856b55af-583b-5a42-a65d-59f7373fb885', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 1, 1, 'You therefore, my child, be strengthened in the grace that is in Christ Jesus.'),
  ('341b0622-71d2-53ec-aeca-4fcf2ad91647', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 2, 2, 'The things which you have heard from me among many witnesses, commit the same to faithful men, who will be able to teach others also.'),
  ('a62ab21a-3a59-56ad-a485-fe901054e7f7', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 3, 3, 'You therefore must endure hardship, as a good soldier of Christ Jesus.'),
  ('94e75f15-ca5c-5918-ad69-dbf3fd2ca14b', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 4, 4, 'No soldier on duty entangles himself in the affairs of life, that he may please him who enrolled him as a soldier.'),
  ('e1625aa4-4ce8-5d12-a643-70ec02ff3e96', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 5, 5, 'Also, if anyone competes in athletics, he isn''t crowned unless he has competed by the rules.'),
  ('99b0cdd6-1e0e-523f-a3dd-1ea10110663d', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 6, 6, 'The farmers who labor must be the first to get a share of the crops.'),
  ('97dc299f-19a3-568a-ae62-1b98a4b10dee', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 7, 7, 'Consider what I say, and may the Lord give you understanding in all things.'),
  ('0ec5e966-0910-5ecb-abdd-906d69c0a840', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 8, 8, 'Remember Jesus Christ, risen from the dead, of the seed of David, according to my Good News,'),
  ('f9a19d88-fe69-5a62-a68f-f056ed4af752', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 9, 9, 'in which I suffer hardship to the point of chains as a criminal. But God''s word isn''t chained.'),
  ('768314be-a1c4-58f0-a937-4d431865d9f9', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 10, 10, 'Therefore I endure all things for the chosen ones'' sake, that they also may obtain the salvation which is in Christ Jesus with eternal glory.'),
  ('6860a284-2e23-5ec2-a039-c0d4e002b385', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 11, 11, 'This saying is faithful: "For if we died with him, we will also live with him.'),
  ('53caa046-4038-5267-ad57-0d46dc27c851', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 12, 12, 'If we endure, we will also reign with him. If we deny him, he also will deny us.'),
  ('d238dfdc-5733-55b1-aa05-752e1c59b24d', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 13, 13, 'If we are faithless, he remains faithful. He can''t deny himself."'),
  ('258253de-5a5b-57ec-ab65-02591fa428be', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 14, 14, 'Remind them of these things, charging them in the sight of the Lord, that they don''t argue about words, to no profit, to the subverting of those who hear.'),
  ('7deb8f5e-31f3-5251-a5b2-655549eff73f', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 15, 15, 'Give diligence to present yourself approved by God, a workman who doesn''t need to be ashamed, properly handling the Word of Truth.'),
  ('deea5c3f-eb46-5683-a1c5-735986790a6f', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 16, 16, 'But shun empty chatter, for they will proceed further in ungodliness,'),
  ('ddb0e046-5a97-5685-a03a-c43788d67baa', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 17, 17, 'and their word will consume like gangrene, of whom is Hymenaeus and Philetus;'),
  ('216bd356-3b41-5be7-ac1a-7e8563ebc79a', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 18, 18, 'men who have erred concerning the truth, saying that the resurrection is already past, and overthrowing the faith of some.'),
  ('4e4a847d-4780-5bb5-a6c3-3cad0d1bace5', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 19, 19, 'However God''s firm foundation stands, having this seal, "The Lord knows those who are his," and, "Let every one who names the name of the Lord depart from unrighteousness."'),
  ('573c96cb-660c-5727-a66f-a49e9611434c', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 20, 20, 'Now in a large house there are not only vessels of gold and of silver, but also of wood and of clay. Some are for honor, and some for dishonor.'),
  ('225f7d6c-d891-56b4-ae46-08b69137f657', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 21, 21, 'If anyone therefore purges himself from these, he will be a vessel for honor, sanctified, and suitable for the master''s use, prepared for every good work.'),
  ('406b5c92-d937-5d76-a041-c1b66aac6f61', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 22, 22, 'Flee from youthful lusts; but pursue righteousness, faith, love, and peace with those who call on the Lord out of a pure heart.'),
  ('7fb879b3-e8ae-54de-abad-c9a164258213', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 23, 23, 'But refuse foolish and ignorant questionings, knowing that they generate strife.'),
  ('9685af05-a46f-59c1-a62f-aee027413e1f', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 24, 24, 'The Lord''s servant must not quarrel, but be gentle towards all, able to teach, patient,'),
  ('ecaa08c5-37c5-50f6-a2ce-fc3fbfc0d85f', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 25, 25, 'in gentleness correcting those who oppose him: perhaps God may give them repentance leading to a full knowledge of the truth,'),
  ('68765e0b-2d18-5af5-a029-d1bec52131ae', 'ed038ae3-2d15-53f0-a986-f9cf5fff1f8f', NULL, 26, 26, 'and they may recover themselves out of the devil''s snare, having been taken captive by him to his will.'),
  ('28219d0a-3b05-58f7-ae57-69593f92c658', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 1, 1, 'But know this, that in the last days, grievous times will come.'),
  ('b7d84f69-d277-52b7-a1d6-383e924b3c22', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 2, 2, 'For men will be lovers of self, lovers of money, boastful, arrogant, blasphemers, disobedient to parents, unthankful, unholy,'),
  ('15e0d867-fbcb-5912-a729-774e5517aa1c', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 3, 3, 'without natural affection, unforgiving, slanderers, without self-control, fierce, no lovers of good,'),
  ('47449efc-fb47-5084-a678-2627a2819591', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 4, 4, 'traitors, headstrong, conceited, lovers of pleasure rather than lovers of God;'),
  ('ebdc2d67-8c1c-54a9-a7f4-363cef3d6aea', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 5, 5, 'holding a form of godliness, but having denied its power. Turn away from these, also.'),
  ('065d598d-d620-59b9-a012-f194879e0f00', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 6, 6, 'For some of these are people who creep into houses, and take captive gullible women loaded down with sins, led away by various lusts,')
